from AlgorithmImports import *
from collections import deque
from datetime import timedelta


class SpyBullishCallAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        )
        self.spy_symbol = self.spy.Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option_symbol = self.option.Symbol
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-500, 500)
                .Expiration(0, 730)
        )

        self.fast_window = deque(maxlen=5)
        self.slow_window = deque(maxlen=20)
        self.previous_fast = None
        self.previous_slow = None

        self.bucket_end = None
        self.bucket_values = {}

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.expiration_date = None
        self.time_stop_date = None
        self.blocked_entry_date = None
        self.equity_liquidation_pending = False

    def OnData(self, slice: Slice):
        now = self.Time
        today = now.date()

        self._handle_unexpected_equity_position()
        self._process_expiration()
        self._evaluate_option_exit(slice)

        bar = slice.Bars.get(self.spy_symbol)
        if bar is not None:
            self._process_minute_bar(bar, slice)

    def _process_minute_bar(self, bar: TradeBar, slice: Slice):
        local_end = bar.EndTime
        if local_end.tzinfo is not None:
            local_end = local_end.replace(tzinfo=None)

        if not (local_end.hour == 9 and local_end.minute >= 31 or
                10 <= local_end.hour <= 15 or
                local_end.hour == 16 and local_end.minute == 0):
            return

        bucket_minute = ((local_end.minute + 4) // 5) * 5
        bucket_end = local_end.replace(
            minute=0,
            second=0,
            microsecond=0
        ) + timedelta(minutes=local_end.hour * 60 + bucket_minute)

        if self.bucket_end is not None and bucket_end != self.bucket_end:
            self._discard_incomplete_bucket()

        if self.bucket_end != bucket_end:
            self.bucket_end = bucket_end
            self.bucket_values = {}

        self.bucket_values[local_end] = bar

        if local_end.minute % 5 != 0:
            return

        if len(self.bucket_values) != 5:
            self.Debug(
                f"Skipped incomplete SPY five-minute bar ending "
                f"{bucket_end:%Y-%m-%d %H:%M}"
            )
            self._discard_incomplete_bucket()
            return

        expected_times = [
            bucket_end - timedelta(minutes=i) for i in range(5, 0, -1)
        ]
        if any(t not in self.bucket_values for t in expected_times):
            self.Debug(
                f"Skipped missing-data SPY five-minute bar ending "
                f"{bucket_end:%Y-%m-%d %H:%M}"
            )
            self._discard_incomplete_bucket()
            return

        closes = [self.bucket_values[t].Close for t in expected_times]
        consolidated_close = closes[-1]

        self.fast_window.append(consolidated_close)
        self.slow_window.append(consolidated_close)

        if len(self.fast_window) == 5 and len(self.slow_window) == 20:
            current_fast = sum(self.fast_window) / 5.0
            current_slow = sum(self.slow_window) / 20.0

            bullish_cross = (
                self.previous_fast is not None and
                self.previous_slow is not None and
                self.previous_fast <= self.previous_slow and
                current_fast > current_slow
            )

            if (
                bullish_cross and
                9 <= bucket_end.hour <= 14 and
                not (
                    bucket_end.hour == 9 and bucket_end.minute < 45
                ) and
                not (
                    bucket_end.hour == 14 and bucket_end.minute > 30
                )
            ):
                self._try_enter(slice, consolidated_close, bucket_end.date())

            self.previous_fast = current_fast
            self.previous_slow = current_slow

        self._discard_incomplete_bucket()

    def _discard_incomplete_bucket(self):
        self.bucket_end = None
        self.bucket_values = {}

    def _try_enter(self, slice: Slice, spy_price: float, current_date):
        if self.blocked_entry_date == current_date:
            return

        if self.held_symbol is not None:
            return

        if self.entry_ticket is not None and self._is_open(self.entry_ticket):
            return

        chain = slice.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug("Skipped call selection: no current SPY option chain")
            return

        minimum_expiry = current_date + timedelta(days=7)
        candidates = [
            contract for contract in chain
            if contract.Right == OptionRight.Call and
            contract.Expiry.date() >= minimum_expiry
        ]

        if not candidates:
            self.Debug("Skipped call selection: no eligible call contracts")
            return

        nearest_expiry = min(
            contract.Expiry.date() for contract in candidates
        )
        strike_floor = 1.01 * spy_price

        strikes = [
            contract for contract in candidates
            if contract.Expiry.date() == nearest_expiry and
            contract.Strike >= strike_floor
        ]

        if not strikes:
            self.Debug(
                f"Skipped call selection: no call strike >= {strike_floor:.2f}"
            )
            return

        selected = min(
            strikes,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="SPY bullish crossover entry"
        )

    def _evaluate_option_exit(self, slice: Slice):
        if self.held_symbol is None:
            return

        if self.exit_ticket is not None and self._is_open(self.exit_ticket):
            return

        chain = slice.OptionChains.get(self.option_symbol)
        contract = None

        if chain is not None:
            for candidate in chain:
                if candidate.Symbol == self.held_symbol:
                    contract = candidate
                    break

        if contract is None:
            midpoint = None
        else:
            bid = contract.BidPrice
            ask = contract.AskPrice
            midpoint = (
                (bid + ask) / 2.0
                if bid is not None and ask is not None and bid > 0 and ask > 0
                else None
            )

        if (
            midpoint is not None and
            self.entry_price is not None and
            midpoint >= 1.50 * self.entry_price
        ):
            self._submit_exit("SPY call 50% profit target")
            return

        if (
            self.time_stop_date == self.Time.date() and
            self.Time.hour == 15 and
            self.Time.minute == 45
        ):
            self._submit_exit("SPY call pre-expiration time stop")

    def _process_expiration(self):
        if self.held_symbol is None or self.expiration_date is None:
            return

        if self.Time.date() >= self.expiration_date:
            self.blocked_entry_date = self.Time.date()
            self._submit_exit("SPY call expiration protection")

    def _submit_exit(self, tag: str):
        if self.held_symbol is None:
            return

        if self.exit_ticket is not None and self._is_open(self.exit_ticket):
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        if self.exit_ticket is not None:
            self.exit_ticket.Cancel("Replacing prior exit order")

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=tag
        )

    def _handle_unexpected_equity_position(self):
        quantity = self.Portfolio[self.spy_symbol].Quantity
        if quantity == 0:
            self.equity_liquidation_pending = False
            return

        if not self.equity_liquidation_pending:
            self.Debug(
                f"Unexpected SPY exercise/assignment position ({quantity}); "
                "liquidating immediately"
            )
            self.MarketOrder(
                self.spy_symbol,
                -quantity,
                tag="Unexpected exercise or assignment liquidation"
            )
            self.equity_liquidation_pending = True

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self.entry_ticket is not None and
            order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.held_symbol = order_event.Symbol
                self.entry_price = order_event.FillPrice
                self.expiration_date = order_event.Symbol.ID.Date.date()
                self.time_stop_date = self._previous_trading_day(
                    self.expiration_date
                )
                self.Debug(
                    f"Entered 1 SPY call {self.held_symbol} at "
                    f"{self.entry_price:.4f}"
                )
                self.entry_ticket = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Rejected
            ):
                self.Debug(
                    f"Skipped entry after order status {order_event.Status}"
                )
                self.entry_ticket = None

        if (
            self.exit_ticket is not None and
            order_event.OrderId == self.exit_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    f"Exited SPY call {order_event.Symbol} at "
                    f"{order_event.FillPrice:.4f}"
                )
                self.held_symbol = None
                self.entry_price = None
                self.expiration_date = None
                self.time_stop_date = None
                self.exit_ticket = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Rejected
            ):
                self.exit_ticket = None

    def OnAssignmentOrderEvent(self, assignment_event: OrderEvent):
        self.Debug("Unexpected option assignment received; liquidating SPY")
        quantity = self.Portfolio[self.spy_symbol].Quantity
        if quantity != 0:
            self.MarketOrder(
                self.spy_symbol,
                -quantity,
                tag="Unexpected assignment liquidation"
            )
        self.blocked_entry_date = self.Time.date()

    def _previous_trading_day(self, date):
        candidate = date - timedelta(days=1)
        while (
            candidate.weekday() >= 5 or
            not self.Securities[self.spy_symbol].Exchange.Hours.IsDateOpen(
                candidate
            )
        ):
            candidate -= timedelta(days=1)
        return candidate

    @staticmethod
    def _is_open(ticket):
        return ticket is not None and ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )

