from AlgorithmImports import *
from datetime import datetime, timedelta


class SpyLongCallCrossover(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity("SPY", Resolution.Minute)
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-100, 100)
                .Expiration(0, 365)
        )

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self.bucket_date = None
        self.bucket_start = None
        self.bucket_closes = {}

        self.spy_price = None
        self.entry_ticket = None
        self.exit_ticket = None
        self.entry_price = None
        self.held_symbol = None
        self.no_entry_date = None
        self.equity_liquidation_ticket = None

    def OnData(self, slice: Slice):
        self._handle_unexpected_spy_position()

        if self.held_symbol is not None:
            self._process_held_option(slice)

        bar = slice.Bars.get(self.spy.Symbol)
        if bar is None:
            return

        self._process_minute_bar(bar, slice)

    def _process_minute_bar(self, bar: TradeBar, slice: Slice):
        minute_start = bar.Time
        local_date = minute_start.date()
        local_time = minute_start.time()

        if local_time < datetime.strptime("09:30", "%H:%M").time():
            return

        if local_time >= datetime.strptime("16:00", "%H:%M").time():
            return

        bucket_minute = (minute_start.minute // 5) * 5
        bucket_start = minute_start.replace(
            minute=bucket_minute,
            second=0,
            microsecond=0
        )

        if self.bucket_date != local_date or self.bucket_start != bucket_start:
            self.bucket_date = local_date
            self.bucket_start = bucket_start
            self.bucket_closes = {}

        self.bucket_closes[minute_start] = bar.Close

        expected_minutes = [
            bucket_start + timedelta(minutes=i)
            for i in range(5)
        ]

        if minute_start != expected_minutes[-1]:
            return

        if any(t not in self.bucket_closes for t in expected_minutes):
            self.bucket_closes = {}
            return

        close = self.bucket_closes[expected_minutes[-1]]
        bar_end = bucket_start + timedelta(minutes=5)
        self.spy_price = close

        previous_ready = self.fast.IsReady and self.slow.IsReady
        previous_fast = self.fast.Current.Value if previous_ready else None
        previous_slow = self.slow.Current.Value if previous_ready else None

        self.fast.Update(bar_end, close)
        self.slow.Update(bar_end, close)

        self.bucket_closes = {}

        if not (previous_ready and self.fast.IsReady and self.slow.IsReady):
            return

        eligible_start = datetime.strptime("09:45", "%H:%M").time()
        eligible_end = datetime.strptime("14:30", "%H:%M").time()
        end_time = bar_end.time()

        bullish = (
            previous_fast <= previous_slow and
            self.fast.Current.Value > self.slow.Current.Value
        )

        if bullish and eligible_start <= end_time <= eligible_end:
            self._try_enter(slice, bar_end.date())

    def _try_enter(self, slice: Slice, algorithm_date):
        if self.no_entry_date == algorithm_date:
            return

        if self.held_symbol is not None:
            return

        if self.entry_ticket is not None and self._ticket_is_open(self.entry_ticket):
            return

        if self.spy_price is None:
            self.Debug("Skipped call selection: SPY price unavailable.")
            return

        contracts = []
        for chain in self._option_chains(slice):
            for contract in chain.Contracts.Values:
                if contract.Right != OptionRight.Call:
                    continue

                expiry_date = contract.Expiry.date()
                days_to_expiry = (expiry_date - algorithm_date).days

                if days_to_expiry < 7:
                    continue

