from collections import deque
from datetime import datetime, timedelta


class SpyBullishCallAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity("SPY", Resolution.Minute)
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)

        self.spy_option = self.AddOption("SPY", Resolution.Minute)
        self.spy_option.SetFilter(
            lambda universe: universe.IncludeWeeklys()
            .Strikes(-100, 100)
            .Expiration(0, 365)
        )

        self.fast_window = deque(maxlen=5)
        self.slow_window = deque(maxlen=20)
        self.previous_fast = None
        self.previous_slow = None

        self.minute_bars = {}
        self.pending_signal = False
        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.no_entry_date = None
        self.underlying_liquidation_ticket = None

    def OnData(self, slice: Slice):
        local_time = self.Time
        current_date = local_time.date()

        self.HandleUnexpectedUnderlyingPosition(current_date)
        self.HandleExpirationProcessing(local_time, current_date)

        if self.spy in slice.Bars:
            self.UpdateFiveMinuteBar(slice.Bars[self.spy], local_time)

        if self.pending_signal:
            self.TryEnter(slice, current_date)

        self.EvaluateExit(slice, local_time, current_date)

    def UpdateFiveMinuteBar(self, minute_bar: TradeBar, local_time: datetime):
        minute_end = local_time.replace(second=0, microsecond=0)

        if minute_end.time() < datetime.strptime("09:31", "%H:%M").time():
            return
        if minute_end.time() > datetime.strptime("16:00", "%H:%M").time():
            return

        session_start = minute_end.replace(hour=9, minute=30)
        minutes_from_start = int((minute_end - session_start).total_seconds() // 60)

        if minutes_from_start < 1:
            return

        bucket_start = session_start + timedelta(
            minutes=(minutes_from_start // 5) * 5
        )
        bucket_end = bucket_start + timedelta(minutes=5)
        key = bucket_start

        if key not in self.minute_bars:
            self.minute_bars[key] = {}

        self.minute_bars[key][minute_end] = minute_bar

        if minute_end == bucket_end:
            bars = self.minute_bars.pop(key, {})
            expected_times = [
                bucket_start + timedelta(minutes=i) for i in range(1, 6)
            ]

            if any(t not in bars for t in expected_times):
                return

            close = bars[expected_times[-1]].Close
            self.ProcessFiveMinuteClose(close, bucket_end)

    def ProcessFiveMinuteClose(self, close: float, bar_end: datetime):
        self.fast_window.append(close)
        self.slow_window.append(close)

        if len(self.fast_window) < 5 or len(self.slow_window) < 20:
            self.previous_fast = None
            self.previous_slow = None
            return

        fast = sum(self.fast_window) / len(self.fast_window)
        slow = sum(self.slow_window) / len(self.slow_window)

        bullish_crossover = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and fast > slow
        )

        if (
            bullish_crossover
            and datetime.strptime("09:45", "%H:%M").time()
            <= bar_end.time()
            <= datetime.strptime("14:30", "%H:%M").time()
        ):
            self.pending_signal = True

        self.previous_fast = fast
        self.previous_slow = slow

    def TryEnter(self, slice: Slice, current_date):
        self.pending_signal = False

        if self.no_entry_date == current_date:
            return

        if self.held_symbol is not None and self.Portfolio[self.held_symbol].Invested:
            return

        if self.entry_ticket is not None and self.IsOpenOrder(self.entry_ticket):
            return

        if self.spy not in slice.Bars:
            self.Debug("Skipped selection: current SPY price unavailable.")
            return

        if self.spy_option.Symbol not in slice.OptionChains:
            self.Debug("Skipped selection: option chain unavailable.")
            return

        spy_price = slice.Bars[self.spy].Close
        chain = slice.OptionChains[self.spy_option.Symbol]

        minimum_expiry = current_date + timedelta(days=7)
        contracts = [
            contract for contract in chain.Contracts.Values
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() >= minimum_expiry
            and contract.Strike >= 1.01 * spy_price
        ]

        if not contracts:
            self.Debug("Skipped selection: no eligible call contract.")
            return

        nearest_expiry = min(contract.Expiry.date() for contract in contracts)
        contracts = [
            contract for contract in contracts
            if contract.Expiry.date() == nearest_expiry
        ]

        selected = sorted(
            contracts,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )[0]

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug("Entry submitted: {}".format(selected.Symbol))

    def EvaluateExit(self, slice: Slice, local_time: datetime, current_date):
        if self.held_symbol is None:
            return

        holding = self.Portfolio[self.held_symbol]
        if not holding.Invested:
            return

        expiry_date = self.held_symbol.ID.Date.date()

        if current_date >= expiry_date:
            self.no_entry_date = current_date
            self.CancelOpenExitOrder()
            self.exit_ticket = self.MarketOrder(
                self.held_symbol, -holding.Quantity
            )
            self.Debug("Exit submitted: expiration processing.")
            return

        previous_trading_day = self.PreviousTradingDay(expiry_date)
        if (
            current_date == previous_trading_day
            and local_time.time() >= datetime.strptime("15:45", "%H:%M").time()
        ):
            if self.exit_ticket is None or not self.IsOpenOrder(self.exit_ticket):
                self.exit_ticket = self.MarketOrder(
                    self.held_symbol, -holding.Quantity
                )
                self.Debug("Exit submitted: pre-expiration time stop.")
            return

        if self.exit_ticket is not None and self.IsOpenOrder(self.exit_ticket):
            return

        if self.spy_option.Symbol not in slice.OptionChains:
            return

        chain = slice.OptionChains[self.spy_option.Symbol]
        if self.held_symbol not in chain.Contracts:
            return

        contract = chain.Contracts[self.held_symbol]
        bid = contract.BidPrice
        ask = contract.AskPrice

        if bid <= 0 or ask <= 0 or self.entry_price is None:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.5 * self.entry_price:
            self.CancelOpenExitOrder()
            self.exit_ticket = self.MarketOrder(
                self.held_symbol, -holding.Quantity
            )
            self.Debug("Exit submitted: 50% profit target.")

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.held_symbol = order_event.Symbol
                self.entry_price = order_event.FillPrice
                self.Debug(
                    "Entry filled: {} at {}".format(
                        self.held_symbol, self.entry_price
                    )
                )

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug("Exit filled: {}".format(order_event.Symbol))
                self.held_symbol = None
                self.entry_price = None
                self.exit_ticket = None
                self.entry_ticket = None

        if order_event.Status == OrderStatus.Filled:
            order = self.Transactions.GetOrderById(order_event.OrderId)
            if order.Type in [OrderType.OptionExercise, OrderType.OptionAssignment]:
                self.no_entry_date = self.Time.date()
                self.Debug(
                    "Unexpected exercise or assignment handled: {}".format(
                        order_event.Symbol
                    )
                )

    def HandleUnexpectedUnderlyingPosition(self, current_date):
        quantity = self.Portfolio[self.spy.Symbol].Quantity
        if quantity == 0:
            return

        self.no_entry_date = current_date

        if (
            self.underlying_liquidation_ticket is None
            or not self.IsOpenOrder(self.underlying_liquidation_ticket)
        ):
            self.underlying_liquidation_ticket = self.MarketOrder(
                self.spy.Symbol, -quantity
            )
            self.Debug("Unexpected SPY position liquidated.")

    def HandleExpirationProcessing(self, local_time: datetime, current_date):
        if self.held_symbol is None:
            return

        if current_date >= self.held_symbol.ID.Date.date():
            self.no_entry_date = current_date

    def PreviousTradingDay(self, date_value):
        candidate = date_value - timedelta(days=1)
        exchange_hours = self.Securities[self.spy.Symbol].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate

    def CancelOpenExitOrder(self):
        if self.exit_ticket is not None and self.IsOpenOrder(self.exit_ticket):
            self.exit_ticket.Cancel("Replacing exit order")

    def IsOpenOrder(self, ticket):
        return ticket.Status in [
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending,
        ]

