                if contract.Symbol == self.held_symbol:
                    quote = contract
                    break
            if quote is not None:
                break

        if quote is None:
            return

        bid = quote.BidPrice
        ask = quote.AskPrice

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if midpoint >= 1.50 * self.entry_price:
            self._submit_exit("50% profit target")

    def _submit_exit(self, reason):
        if self.held_symbol is None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity <= 0:
            return

        if self.exit_ticket is not None and self._order_is_open(self.exit_ticket):
            return

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )
        self.Debug(f"Exit submitted: {self.held_symbol} ({reason})")

    def _handle_unexpected_equity_position(self):
        quantity = self.Portfolio[self.spy_symbol].Quantity

        if quantity == 0:
            return

        if (
            self.equity_liquidation_ticket is not None
            and self._order_is_open(self.equity_liquidation_ticket)
        ):
            return

        self.Debug(
            f"Unexpected exercise or assignment handling: "
            f"liquidating {quantity} SPY shares."
        )
        self.equity_liquidation_ticket = self.MarketOrder(
            self.spy_symbol,
