        if self.spy not in data.Bars:
            return

        spy_bar = data.Bars[self.spy]
        local_time = self.Time.replace(second=0, microsecond=0)

        consolidated_close = self._update_five_minute_bar(spy_bar, local_time)
        if consolidated_close is None:
            return

        self.closes.Add(consolidated_close)

        if not self.closes.IsReady:
            return

        if local_time.time() < time(9, 45) or local_time.time() > time(14, 30):
            return

        if self.held_symbol is not None or self._entry_order_is_open():
            return

        fast_current = sum(
            self.closes[i] for i in range(self.fast_period)
        ) / self.fast_period

        slow_current = sum(
            self.closes[i] for i in range(self.slow_period)
        ) / self.slow_period

        previous_values = [
            self.closes[i] for i in range(1, self.slow_period)
        ]

        fast_previous = sum(
            previous_values[i] for i in range(self.fast_period)
        ) / self.fast_period

        slow_previous = sum(previous_values) / len(previous_values)

        bullish_cross = (
            fast_previous <= slow_previous and
            fast_current > slow_current
        )

        if bullish_cross:
            self._try_enter(data, spy_bar.Close)

    def _update_five_minute_bar(self, minute_bar, local_time):
        if local_time.time() < time(9, 30) or local_time.time() > time(16, 0):
            return None

        bucket_end_minute = ((local_time.minute + 4) // 5) * 5
        bucket_end = local_time.replace(
            minute=0
        ) + timedelta(minutes=bucket_end_minute)

        if bucket_end.date() != local_time.date():
            return None

        key = bucket_end
        bucket = self.buckets.setdefault(key, {})
        bucket[local_time] = minute_bar

        if local_time != bucket_end:
            return None

