            bucket_end - timedelta(minutes=i)
            for i in range(4, -1, -1)
        ]

        if any(expected_time not in bucket for expected_time in expected_times):
            self.Debug(
                "Skipped incomplete five-minute SPY bar ending {}".format(
                    bucket_end.strftime("%Y-%m-%d %H:%M")
                )
            )
            return None

        bars = [bucket[t] for t in expected_times]
        return bars[-1].Close

