        today = self.Time.date()
        minimum_expiry = today + timedelta(days=7)
        candidates = []

        for chain in data.OptionChains.Values:
            for contract in chain:
                expiry = contract.Expiry.date()

                if expiry < minimum_expiry:
                    continue
                if contract.Right != OptionRight.Call:
                    continue

                candidates.append(contract)

        if not candidates:
            self.Debug("Skipped call selection: no eligible option contracts")
            return

        expiries = sorted({contract.Expiry.date() for contract in candidates})
        selected_expiry = expiries[0]

        minimum_strike = 1.01 * float(spy_price)
        strike_candidates = [
            contract for contract in candidates
            if contract.Expiry.date() == selected_expiry
            and float(contract.Strike) >= minimum_strike
        ]

        if not strike_candidates:
            self.Debug("Skipped call selection: no strike at least 1% OTM")
            return

        strike_candidates.sort(
            key=lambda contract: (
                float(contract.Strike),
                str(contract.Symbol)
            )
        )

        selected = strike_candidates[0]
        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.entry_order_id = self.entry_ticket.OrderId

        self.Debug(
            "Submitted call entry: {} expiration {} strike {}".format(
                selected.Symbol,
                selected_expiry,
                selected.Strike
            )
        )

    def _process_option_exit(self, data):
        if self.held_symbol is None or self.entry_fill_price is None:
            return

        if self.exit_ticket is not None and not self.exit_ticket.Status.IsOpen():
            self.exit_ticket = None

        held_quantity = self.Portfolio[self.held_symbol].Quantity
        if held_quantity <= 0:
            return

        contract = None
        for chain in data.OptionChains.Values:
            for candidate in chain:
                if candidate.Symbol == self.held_symbol:
                    contract = candidate
                    break
            if contract is not None:
                break

        target_reached = False
        if contract is not None:
            bid = float(contract.BidPrice)
            ask = float(contract.AskPrice)

            if bid > 0 and ask > 0:
                midpoint = (bid + ask) / 2.0
                target_reached = midpoint >= 1.50 * self.entry_fill_price

        expiry = self.held_symbol.ID.Date.date()
        previous_trading_day = self._previous_trading_day(expiry)
        time_stop = (
            self.Time.date() == previous_trading_day and
            self.Time.time() >= time(15, 45)
        )

        if target_reached:
            self._submit_option_exit(
                held_quantity,
                "50% profit target"
            )
        elif time_stop:
            self._submit_option_exit(
                held_quantity,
                "expiration time stop"
            )

    def _process_expiration(self, current_date):
        if self.held_symbol is None:
            return

        expiry = self.held_symbol.ID.Date.date()
        if current_date < expiry:
            return

        self.expiry_block_date = current_date
        quantity = self.Portfolio[self.held_symbol].Quantity

        if quantity > 0:
            self._submit_option_exit(quantity, "expiration protection")
            self.Debug(
                "Unexpected option position at expiration; liquidation submitted"
            )

    def _submit_option_exit(self, quantity, reason):
        if quantity <= 0 or self.held_symbol is None:
            return

        if self.exit_ticket is not None and self.exit_ticket.Status.IsOpen():
            self.exit_ticket.Cancel("Replacing option exit order")

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )
        self.Debug(
            "Submitted option exit for {} contract(s): {}".format(
                quantity,
                reason
            )
        )

    def _handle_unexpected_spy_position(self, data):
        quantity = self.Portfolio[self.spy].Quantity

        if quantity == 0:
            self.spy_cleanup_ticket = None
            return

        if (
            self.spy_cleanup_ticket is None or
            not self.spy_cleanup_ticket.Status.IsOpen()
        ):
            self.spy_cleanup_ticket = self.MarketOrder(
                self.spy,
                -quantity,
                tag="Unexpected exercise or assignment liquidation"
            )
            self.Debug(
                "Unexpected SPY equity position detected; liquidation submitted"
            )

    def _entry_order_is_open(self):
        return (
            self.entry_ticket is not None and
            self.entry_ticket.Status.IsOpen()
        )

    def _previous_trading_day(self, expiry_date):
        candidate = expiry_date - timedelta(days=1)

        while not self.Securities[self.spy].Exchange.Hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self.entry_order_id is not None and
            order_event.OrderId == self.entry_order_id and
            order_event.Status == OrderStatus.Filled
        ):
            self.held_symbol = order_event.Symbol
            self.entry_fill_price = float(order_event.FillPrice)
            self.Debug(
                "Call entry filled: {} at {}".format(
                    self.held_symbol,
                    self.entry_fill_price
                )
            )

        if (
            self.exit_ticket is not None and
            order_event.OrderId == self.exit_ticket.OrderId and
            order_event.Status == OrderStatus.Filled
        ):
            self.Debug("Option position exited: {}".format(order_event.Symbol))
            self.held_symbol = None
            self.entry_fill_price = None
            self.exit_ticket = None
            self.entry_ticket = None
            self.entry_order_id = None

