from AlgorithmImports import *
from datetime import timedelta


class SpyCallCrossoverAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        self.spy = self.AddEquity("SPY", Resolution.Minute)
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)

        self.spy_option = self.AddOption("SPY", Resolution.Minute)
        self.spy_option.SetFilter(
            lambda universe: universe.Strikes(-100, 100).Expiration(0, 365)
        )

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self._consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self._consolidator.DataConsolidated += self._on_five_minute_bar
        self.SubscriptionManager.AddConsolidator(
            self.spy.Symbol, self._consolidator
        )

        self._previous_fast = None
        self._previous_slow = None
        self._pending_entry = False
        self._pending_entry_time = None

        self._entry_ticket = None
        self._held_symbol = None
        self._entry_price = None
        self._exit_ticket = None
        self._no_entry_date = None
        self._equity_liquidation_pending = False

    def _on_five_minute_bar(self, sender, bar):
        bar_time = bar.EndTime.time()

        if not (
            bar_time >= time(9, 30) and bar_time <= time(16, 0)
        ):
            return

        previous_fast = self.fast.Current.Value if self.fast.IsReady else None
        previous_slow = self.slow.Current.Value if self.slow.IsReady else None

        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        if (
            previous_fast is not None
            and previous_slow is not None
            and self.fast.IsReady
            and self.slow.IsReady
            and previous_fast <= previous_slow
            and self.fast.Current.Value > self.slow.Current.Value
            and time(9, 45) <= bar_time <= time(14, 30)
        ):
            self._pending_entry = True
            self._pending_entry_time = bar.EndTime

        self._previous_fast = previous_fast
        self._previous_slow = previous_slow

    def OnData(self, data):
        current_date = self.Time.date()

        self._handle_unexpected_equity_position()

        if self._held_symbol is not None:
            self._handle_expiration_processing(current_date)
            self._evaluate_exit(data)

        if (
            self._pending_entry
            and self._pending_entry_time is not None
            and self._pending_entry_time.date() == current_date
        ):
            self._pending_entry = False
            self._try_enter(data)

    def _try_enter(self, data):
        if self._no_entry_date == self.Time.date():
            return

        if self._held_symbol is not None or self._entry_ticket is not None:
            return

        if self.spy.Symbol not in data.Bars:
            self.Debug("Skipped entry: current SPY price unavailable.")
            return

        spy_price = data.Bars[self.spy.Symbol].Close
        if spy_price <= 0:
            self.Debug("Skipped entry: invalid SPY price.")
            return

        selected = self._select_contract(data, spy_price)
        if selected is None:
            self.Debug("Skipped entry: no qualifying call contract.")
            return

        self._entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )

    def _select_contract(self, data, spy_price):
        chains = data.OptionChains
        if chains is None:
            return None

        minimum_expiry = self.Time.date() + timedelta(days=7)
        candidates = []

        for chain in chains.Values:
            for contract in chain:
                if contract.Right != OptionRight.Call:
                    continue

                expiry_date = contract.Expiry.date()
                if expiry_date < minimum_expiry:
                    continue

                if contract.Strike < 1.01 * spy_price:
                    continue

                candidates.append(contract)

        if not candidates:
            return None

        nearest_expiry = min(c.Expiry.date() for c in candidates)
        same_expiry = [
            c for c in candidates if c.Expiry.date() == nearest_expiry
        ]

        same_expiry.sort(
            key=lambda c: (c.Strike, str(c.Symbol))
        )
        return same_expiry[0]

    def _evaluate_exit(self, data):
        if self._held_symbol is None or self._entry_price is None:
            return

        if self._exit_ticket is not None:
            if self._exit_ticket.Status in (
                OrderStatus.New,
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled,
                OrderStatus.CancelPending,
            ):
                return

        if self._held_symbol not in data.QuoteBars:
            return

        quote = data.QuoteBars[self._held_symbol]
        bid = quote.Bid.Close
        ask = quote.Ask.Close

        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2
        if midpoint >= 1.50 * self._entry_price:
            self._submit_exit("50% profit target")

    def _handle_expiration_processing(self, current_date):
        if self._held_symbol is None:
            return

        expiry_date = self.Securities[self._held_symbol].Symbol.ID.Date.date()

        if current_date >= expiry_date:
            self._no_entry_date = current_date
            self._submit_exit("expiration protection")
            return

        previous_trading_day = self._previous_trading_day(expiry_date)
        if (
            current_date == previous_trading_day
            and self.Time.hour == 15
            and self.Time.minute == 45
        ):
            self._submit_exit("pre-expiration time stop")

    def _previous_trading_day(self, expiry_date):
        candidate = expiry_date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy.Symbol].Exchange.Hours

