        self.slow = SimpleMovingAverage(20)

        self._consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self._consolidator.DataConsolidated += self._on_five_minute_bar
        self.SubscriptionManager.AddConsolidator(
            self.spy.Symbol, self._consolidator
        )

        self._previous_fast = None
        self._previous_slow = None
        self._pending_entry = False
        self._pending_entry_time = None

        self._entry_ticket = None
        self._held_symbol = None
        self._entry_price = None
        self._exit_ticket = None
        self._no_entry_date = None
        self._equity_liquidation_pending = False

    def _on_five_minute_bar(self, sender, bar):
        bar_time = bar.EndTime.time()

        if not (
            bar_time >= time(9, 30) and bar_time <= time(16, 0)
        ):
            return

        previous_fast = self.fast.Current.Value if self.fast.IsReady else None
        previous_slow = self.slow.Current.Value if self.slow.IsReady else None

        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        if (
            previous_fast is not None
            and previous_slow is not None
            and self.fast.IsReady
            and self.slow.IsReady
            and previous_fast <= previous_slow
            and self.fast.Current.Value > self.slow.Current.Value
            and time(9, 45) <= bar_time <= time(14, 30)
        ):
            self._pending_entry = True
            self._pending_entry_time = bar.EndTime

        self._previous_fast = previous_fast
        self._previous_slow = previous_slow

    def OnData(self, data):
        current_date = self.Time.date()

        self._handle_unexpected_equity_position()

        if self._held_symbol is not None:
            self._handle_expiration_processing(current_date)
            self._evaluate_exit(data)

        if (
            self._pending_entry
            and self._pending_entry_time is not None
            and self._pending_entry_time.date() == current_date
        ):
            self._pending_entry = False
            self._try_enter(data)

    def _try_enter(self, data):
        if self._no_entry_date == self.Time.date():
            return

        if self._held_symbol is not None or self._entry_ticket is not None:
            return

        if self.spy.Symbol not in data.Bars:
            self.Debug("Skipped entry: current SPY price unavailable.")
            return

        spy_price = data.Bars[self.spy.Symbol].Close
        if spy_price <= 0:
            self.Debug("Skipped entry: invalid SPY price.")
            return

        selected = self._select_contract(data, spy_price)
        if selected is None:
            self.Debug("Skipped entry: no qualifying call contract.")
            return

        self._entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )

    def _select_contract(self, data, spy_price):
        chains = data.OptionChains
        if chains is None:
            return None

        minimum_expiry = self.Time.date() + timedelta(days=7)
        candidates = []

