            self._evaluate_exit(slice)
            return

        self._process_minute_bar(spy_bar, slice)
        self._evaluate_exit(slice)

    def _process_minute_bar(self, bar: TradeBar, slice: Slice):
        end = bar.EndTime.replace(second=0, microsecond=0)
        local_time = end.time()

        if local_time < time(9, 31) or local_time > time(16, 0):
            return

        minute_number = end.hour * 60 + end.minute
        bucket_end_minute = minute_number + (5 - minute_number % 5)
        bucket_end = end.replace(
            hour=bucket_end_minute // 60,
            minute=bucket_end_minute % 60
        )
        bucket_key = bucket_end

        if self.minute_bucket is not None and bucket_key != self.minute_bucket["end"]:
            self._complete_bucket(self.minute_bucket, slice)

        if self.minute_bucket is None or bucket_key != self.minute_bucket["end"]:
            self.minute_bucket = {
                "end": bucket_end,
                "bars": {}
            }

        self.minute_bucket["bars"][end] = bar

        if end == bucket_end:
            completed = self.minute_bucket
            self.minute_bucket = None
            self._complete_bucket(completed, slice)

    def _complete_bucket(self, bucket, slice: Slice):
        bars = bucket["bars"]
        end = bucket["end"]

        expected = [
            end - timedelta(minutes=i)
            for i in range(4, -1, -1)
        ]

        if any(t not in bars for t in expected):
            return

        closes = [bars[t].Close for t in expected]

        self.previous_fast = self.fast.Current.Value if self.fast.IsReady else None
        self.previous_slow = self.slow.Current.Value if self.slow.IsReady else None

        self.fast.Update(end, closes[-1])
        self.slow.Update(end, closes[-1])

        if not self.fast.IsReady or not self.slow.IsReady:
            return

        if self.previous_fast is None or self.previous_slow is None:
            return

        bullish_cross = (
            self.previous_fast <= self.previous_slow
            and self.fast.Current.Value > self.slow.Current.Value
        )

        end_time = end.time()
        if (
            bullish_cross
            and time(9, 45) <= end_time <= time(14, 30)
            and self._can_enter()
        ):
            self._try_enter(slice, closes[-1])

    def _can_enter(self):
        if self.held_symbol is not None:
            return False

        if self.entry_ticket is not None and self._is_open(self.entry_ticket.Status):
            return False

        if self.no_entry_date == self.Time.date():
            return False

        return True

    def _try_enter(self, slice: Slice, spy_price: float):
        today = self.Time.date()
        minimum_expiry = today + timedelta(days=7)

        candidates = []

        for chain in slice.OptionChains.Values:
            for contract in chain:
                if contract.Right != OptionRight.Call:
                    continue

                expiry = contract.Expiry.date()
                if expiry < minimum_expiry:
                    continue

                if contract.Strike < 1.01 * spy_price:
                    continue

                candidates.append(contract)

        if not candidates:
            self.Debug("Skipped option selection: no qualifying call contract.")
            return

        expiration = min(c.Expiry.date() for c in candidates)
        candidates = [
            c for c in candidates
            if c.Expiry.date() == expiration
        ]

        selected = min(
            candidates,
            key=lambda c: (c.Strike, str(c.Symbol))
        )

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )

    def _evaluate_exit(self, slice: Slice):
        if self.held_symbol is None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity <= 0:
            return

        expiry_date = self.held_symbol.ID.Date.date()
        today = self.Time.date()

        if today >= expiry_date:
            self.no_entry_date = today
            self._submit_exit("Expiration protection")
            return

        prior_trading_day = self._prior_trading_day(expiry_date)
        if (
            today == prior_trading_day
            and self.Time.time() >= time(15, 45)
        ):
            self._submit_exit("Pre-expiration time stop")
            return

        quote = slice.QuoteBars.get(self.held_symbol)
        if quote is None or quote.Bid is None or quote.Ask is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close

        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if self.entry_price is not None and midpoint >= 1.50 * self.entry_price:
            self._submit_exit("50% profit target")

    def _submit_exit(self, reason: str):
        if self.held_symbol is None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity <= 0:
            return

        if self.exit_ticket is not None and self._is_open(self.exit_ticket.Status):
            return

        self.Transactions.CancelOpenOrders(self.held_symbol)

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )
        self.Debug(
            "Exit submitted: {0} ({1})".format(
                self.held_symbol,
                reason
            )
        )

    def _prior_trading_day(self, expiry_date: date):
        current = expiry_date - timedelta(days=1)
        while not self.Securities[self.spy].Exchange.Hours.IsDateOpen(current):
            current -= timedelta(days=1)
        return current

    def _handle_unexpected_equity_position(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0 or self.equity_liquidation_submitted:
            return

        self.equity_liquidation_submitted = True
        self.MarketOrder(
            self.spy,
            -quantity,
            tag="Unexpected exercise or assignment liquidation"
        )
        self.no_entry_date = self.Time.date()
        self.Debug("Unexpected SPY exercise or assignment; equity position liquidated.")

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.Status not in [OrderStatus.Filled, OrderStatus.PartiallyFilled]:
            if (
                self.entry_ticket is not None
                and order_event.OrderId == self.entry_ticket.OrderId
                and order_event.Status in [
                    OrderStatus.Canceled,
                    OrderStatus.Invalid
                ]
            ):
                self.entry_ticket = None
            return

        order = self.Transactions.GetOrderById(order_event.OrderId)

        if order.Type == OrderType.OptionExercise:
            self.no_entry_date = self.Time.date()
            self.Debug("Unexpected option exercise or assignment processed.")

        if order.Symbol == self.spy:
            if order_event.Status == OrderStatus.Filled:
                self.equity_liquidation_submitted = False
            return

        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
            and order_event.FillQuantity > 0
        ):
            self.held_symbol = order.Symbol
            self.entry_price = order_event.FillPrice
            self.Debug(
                "Entry filled: {0}, price {1:.4f}".format(
                    self.held_symbol,
                    self.entry_price
                )
            )
            return

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
            and order_event.Status == OrderStatus.Filled
        ):
            self.Debug("Exit filled: {0}".format(order.Symbol))
            self.held_symbol = None
            self.entry_price = None
            self.exit_ticket = None
            self.entry_ticket = None

    @staticmethod
    def _is_open(status):
        return status in [
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending
        ]

