        ticket = self.MarketOrder(
            self.spy,
            -quantity,
            tag="Unexpected exercise or assignment liquidation"
        )
        self.unexpected_spy_liquidation_id = ticket.OrderId

    def IsRegularSessionMinute(self, value: datetime) -> bool:
        minutes = value.hour * 60 + value.minute
        return 570 <= minutes < 960

    def IsTradingDayImmediatelyBeforeExpiry(
        self,
        current_date,
        expiry_date
    ) -> bool:
        candidate = expiry_date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

