        self.slow = SimpleMovingAverage(20)

        self.previous_fast = None
        self.previous_slow = None

        self.bucket_start = None
        self.bucket_last_minute = None
        self.bucket_count = 0
        self.bucket_valid = True
        self.bucket_close = None

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_option = None
        self.entry_price = None
        self.expiration_processed_date = None
        self.blocked_entry_date = None

    def OnData(self, slice: Slice):
        current_date = self.Time.date()

        self._handle_unexpected_spy_position(current_date)

        if self.held_option is not None:
            expiration_date = self.held_option.ID.Date.date()

            if current_date >= expiration_date:
                if self.expiration_processed_date != current_date:
                    self.expiration_processed_date = current_date
                    self.blocked_entry_date = current_date
                    self.Debug(
                        f"{self.Time}: expiration processing; liquidating "
                        f"{self.held_option}"
                    )
                    self._submit_exit("expiration")
            else:
                previous_trading_day = self._previous_trading_day(expiration_date)

                if (
                    current_date == previous_trading_day
                    and self.Time.time() >= datetime.strptime(
                        "15:45", "%H:%M"
                    ).time()
                ):
                    self._submit_exit("time stop")

                self._check_profit_target(slice)

        spy_bar = slice.Bars.get(self.spy.Symbol)
        if spy_bar is None:
            return

        self._update_five_minute_bar(spy_bar, slice)

    def _update_five_minute_bar(self, minute_bar: TradeBar, slice: Slice):
        bar_time = minute_bar.EndTime - timedelta(minutes=1)
        bar_date = bar_time.date()
        bar_clock = bar_time.time()

        if bar_clock < datetime.strptime("09:30", "%H:%M").time():
            return

        if bar_clock >= datetime.strptime("16:00", "%H:%M").time():
            self._flush_bucket(slice)
            return

        bucket_minute = (bar_time.minute // 5) * 5
        bucket_start = bar_time.replace(
            minute=bucket_minute,
            second=0,
            microsecond=0
        )

        if self.bucket_start != bucket_start:
            self._flush_bucket(slice)

            self.bucket_start = bucket_start
            self.bucket_last_minute = bar_time
            self.bucket_count = 1
            self.bucket_valid = True
            self.bucket_close = minute_bar.Close
            return

        expected_time = self.bucket_last_minute + timedelta(minutes=1)

        if bar_time != expected_time:
            self.bucket_valid = False

        self.bucket_last_minute = bar_time
        self.bucket_count += 1
        self.bucket_close = minute_bar.Close

    def _flush_bucket(self, slice: Slice):
        if self.bucket_start is None:
            return

        complete = (
            self.bucket_valid
            and self.bucket_count == 5
            and self.bucket_last_minute
            == self.bucket_start + timedelta(minutes=4)
        )

        if complete:
            self._process_completed_five_minute_bar(
                self.bucket_last_minute + timedelta(minutes=1),
                self.bucket_close,
                slice
            )

        self.bucket_start = None
        self.bucket_last_minute = None
        self.bucket_count = 0
        self.bucket_valid = True
        self.bucket_close = None

    def _process_completed_five_minute_bar(
        self,
        bar_end_time: datetime,
        close: float,
        slice: Slice
    ):
        self.fast.Update(bar_end_time, close)
        self.slow.Update(bar_end_time, close)

        if (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.fast.IsReady
            and self.slow.IsReady
        ):
            bullish_cross = (
                self.previous_fast <= self.previous_slow
                and self.fast.Current.Value > self.slow.Current.Value
            )

            end_clock = bar_end_time.time()
            eligible_start = datetime.strptime("09:45", "%H:%M").time()
            eligible_end = datetime.strptime("14:30", "%H:%M").time()

            if (
                bullish_cross
                and eligible_start <= end_clock <= eligible_end
            ):
                self._try_enter(slice)

        if self.fast.IsReady and self.slow.IsReady:
            self.previous_fast = self.fast.Current.Value
            self.previous_slow = self.slow.Current.Value

    def _try_enter(self, slice: Slice):
        current_date = self.Time.date()

        if current_date == self.blocked_entry_date:
            return

        if self.held_option is not None:
            return

        if self._order_is_open(self.entry_ticket):
            return

        if self._order_is_open(self.exit_ticket):
            return

        spy_price = self.Securities[self.spy.Symbol].Price
        if spy_price <= 0:
            self.Debug(f"{self.Time}: skipped option selection; invalid SPY price")
            return

        minimum_expiration = current_date + timedelta(days=7)
        candidates = []

        for chain in slice.OptionChains.Values:
            for contract in chain.Contracts.Values:
                symbol = contract.Symbol

                if symbol.ID.OptionRight != OptionRight.Call:
                    continue

                expiration_date = symbol.ID.Date.date()
                if expiration_date < minimum_expiration:
                    continue

                if symbol.ID.Strike < 1.01 * spy_price:
                    continue

                candidates.append(contract)

        if not candidates:
            self.Debug(f"{self.Time}: skipped option selection; no qualifying call")
            return

        nearest_expiration = min(
            contract.Symbol.ID.Date.date() for contract in candidates
        )

        candidates = [
            contract for contract in candidates
            if contract.Symbol.ID.Date.date() == nearest_expiration
        ]

        selected = min(
            candidates,
            key=lambda contract: (
                contract.Symbol.ID.Strike,
                str(contract.Symbol)
            )
        )

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="bullish five-minute crossover entry"
        )

    def _check_profit_target(self, slice: Slice):
        if self.held_option is None or self.entry_price is None:
            return

        if self._order_is_open(self.exit_ticket):
            return

        contract = self._find_contract(slice, self.held_option)
        if contract is None:
            return

        bid = contract.BidPrice
        ask = contract.AskPrice

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if midpoint >= 1.50 * self.entry_price:
            self._submit_exit("50% profit target")

    def _submit_exit(self, reason: str):
        if self.held_option is None:
            return

        if self._order_is_open(self.exit_ticket):
            return

        if self.entry_ticket is not None and self._order_is_open(
            self.entry_ticket
        ):
            self.entry_ticket.Cancel("exit requested before entry completed")
            return

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity == 0:
            return

        if self.exit_ticket is not None and self._order_is_open(
            self.exit_ticket
        ):
            self.exit_ticket.Cancel("replaced by liquidation order")

        self.exit_ticket = self.MarketOrder(
            self.held_option,
            -quantity,
