        signal = self._add_minute_to_five_minute_bar(spy_bar)
        if signal and self._eligible_for_entry(current_date):
            self._try_enter(data, spy_bar.Close, current_date)

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_order_id == order_event.OrderId:
            if order_event.Status in (OrderStatus.Filled, OrderStatus.PartiallyFilled):
                fill_quantity = abs(order_event.FillQuantity)
                if fill_quantity > 0:
                    prior_value = self.entry_fill_price * self.entry_filled_quantity \
                        if self.entry_fill_price is not None else Decimal(0)
                    self.entry_filled_quantity += fill_quantity
                    self.entry_fill_price = (
                        prior_value + order_event.FillPrice * fill_quantity
                    ) / self.entry_filled_quantity

                if order_event.Status == OrderStatus.Filled:
                    self.Debug(
                        f"ENTRY FILLED {self.entry_symbol} "
                        f"qty={self.entry_filled_quantity} "
                        f"price={self.entry_fill_price}"
                    )
                    self.entry_ticket = None
                    self.entry_order_id = None

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.None
            ):
                self.Debug(f"ENTRY ORDER NOT FILLED: {order_event.Status}")
                self.entry_ticket = None
                self.entry_order_id = None
                self.entry_symbol = None
                self.entry_fill_price = None
                self.entry_filled_quantity = 0

        if self.exit_order_id == order_event.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    f"EXIT FILLED {self.held_symbol} "
                    f"price={order_event.FillPrice}"
                )
                self.exit_ticket = None
                self.exit_order_id = None
                self.held_symbol = None
                self.entry_fill_price = None
                self.entry_filled_quantity = 0

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.exit_ticket = None
                self.exit_order_id = None

    def _add_minute_to_five_minute_bar(self, minute_bar):
        end_time = minute_bar.EndTime
        if end_time.hour < 9 or end_time.hour > 16:
            return False

        if end_time.hour == 9 and end_time.minute < 31:
            return False

        if end_time.hour == 16 and end_time.minute > 0:
            return False

        minute = end_time.minute
        bucket_end_minute = ((minute - 1) // 5 + 1) * 5
        bucket_end = end_time.replace(
            minute=0,
            second=0,
            microsecond=0
        ) + timedelta(minutes=bucket_end_minute)

        key = bucket_end
        bucket = self.minute_buckets.setdefault(key, {})
        bucket[end_time] = minute_bar

        completed = False

        if end_time.minute % 5 == 0:
            expected_times = [
                bucket_end - timedelta(minutes=i)
                for i in range(1, 6)
            ]

            if all(t in bucket for t in expected_times):
                bars = [bucket[t] for t in sorted(expected_times)]
                consolidated = TradeBar(
                    bucket_end,
                    self.spy_symbol,
                    bars[0].Open,
                    max(x.High for x in bars),
                    min(x.Low for x in bars),
                    bars[-1].Close,
                    sum(x.Volume for x in bars),
                    timedelta(minutes=5)
                )
                completed = self._update_averages(consolidated)

            del self.minute_buckets[key]

            stale_keys = [
                k for k in self.minute_buckets
                if k < bucket_end
            ]
            for stale_key in stale_keys:
                del self.minute_buckets[stale_key]

        return completed

    def _update_averages(self, bar):
        had_previous_values = (
            self.fast.IsReady and
            self.slow.IsReady and
            self.previous_fast is not None and
            self.previous_slow is not None
        )

        if self.fast.IsReady:
            self.previous_fast = self.fast.Current.Value
        if self.slow.IsReady:
            self.previous_slow = self.slow.Current.Value

        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        if not self.fast.IsReady or not self.slow.IsReady:
            return False

        if not had_previous_values:
            return False

        bullish_cross = (
            self.previous_fast <= self.previous_slow and
            self.fast.Current.Value > self.slow.Current.Value
        )

        end_time = bar.EndTime
        return (
            bullish_cross and
            (
                end_time.hour > 9 or
                (end_time.hour == 9 and end_time.minute >= 45)
            ) and
            (
                end_time.hour < 14 or
                (end_time.hour == 14 and end_time.minute <= 30)
            )
        )

    def _eligible_for_entry(self, current_date):
        return (
            self.no_entry_date != current_date and
            self.held_symbol is None and
            self.entry_order_id is None
        )

    def _try_enter(self, data, spy_price, current_date):
        selected = None
        selected_expiry = None
        minimum_expiry = current_date + timedelta(days=7)
        minimum_strike = Decimal(str(spy_price)) * Decimal("1.01")

        for chain in data.OptionChains:
            for contract in chain.Value:
                expiry_date = contract.Expiry.date()

                if expiry_date < minimum_expiry:
                    continue
                if contract.Right != OptionRight.Call:
                    continue
                if contract.Strike < minimum_strike:
                    continue

                if selected is None or (
                    expiry_date < selected_expiry or
                    (
                        expiry_date == selected_expiry and
                        (
                            contract.Strike < selected.Strike or
                            (
                                contract.Strike == selected.Strike and
                                str(contract.Symbol) < str(selected.Symbol)
                            )
                        )
                    )
                ):
                    selected = contract
                    selected_expiry = expiry_date

        if selected is None:
            self.Debug("ENTRY SKIPPED: no qualifying call contract")
            return

        self.entry_symbol = selected.Symbol
        self.entry_fill_price = None
        self.entry_filled_quantity = 0

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.entry_order_id = self.entry_ticket.OrderId

        self.Debug(f"ENTRY SUBMITTED {selected.Symbol}")

    def _evaluate_existing_position(self, data, current_date):
        if self.held_symbol is None:
            return

        holding = self.Portfolio[self.held_symbol]
        if not holding.Invested:
            return

        expiry_date = self.Securities[self.held_symbol].Symbol.ID.Date.date()

        if current_date >= expiry_date:
            self.no_entry_date = current_date
            self._submit_exit("expiration processing")
            return

        if self._is_immediately_preceding_trading_day(current_date, expiry_date):
            if self.Time.hour == 15 and self.Time.minute >= 45:
                self._submit_exit("expiration time stop")
                return

        quote = data.QuoteBars.get(self.held_symbol)
        if quote is None or quote.Bid is None or quote.Ask is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close

        if (
            bid is None or ask is None or
            bid <= 0 or ask <= 0 or
            self.entry_fill_price is None
        ):
            return

        midpoint = (bid + ask) / Decimal(2)
        if midpoint >= self.entry_fill_price * Decimal("1.50"):
            self._submit_exit("50% profit target")

    def _submit_exit(self, reason):
        if self.held_symbol is None:
            return

        if self.exit_order_id is not None:
            return

        self._cancel_open_exit_orders()

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity
        )
        self.exit_order_id = self.exit_ticket.OrderId
        self.Debug(f"EXIT SUBMITTED ({reason}) {self.held_symbol}")

    def _cancel_open_exit_orders(self):
        if self.exit_ticket is not None:
            status = self.exit_ticket.Status
            if status in (
                OrderStatus.New,
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled
            ):
                self.exit_ticket.Cancel("Replaced by liquidation order")

    def _process_expiration(self, current_date):
        if self.held_symbol is None:
            return

        expiry_date = self.Securities[self.held_symbol].Symbol.ID.Date.date()
        if current_date >= expiry_date:
            self.no_entry_date = current_date
            self._submit_exit("expiration processing")

    def _handle_unexpected_spy_position(self, current_date):
        quantity = self.Portfolio[self.spy_symbol].Quantity
        if quantity == 0:
            return

        if self.assignment_handled_date != current_date:
            self.Debug(
                f"UNEXPECTED SPY EQUITY POSITION; liquidating qty={quantity}"
            )
            self.assignment_handled_date = current_date

        self.no_entry_date = current_date
        self.MarketOrder(self.spy_symbol, -quantity)

    def _is_immediately_preceding_trading_day(self, current_date, expiry_date):
        candidate = expiry_date - timedelta(days=1)

        while not self._is_trading_day(candidate):
            candidate -= timedelta(days=1)

        return current_date == candidate

    def _is_trading_day(self, date_value):
        exchange_hours = self.Securities[self.spy_symbol].Exchange.Hours
        date_time = datetime(
            date_value.year,
            date_value.month,
            date_value.day
        )
        return exchange_hours.IsDateOpen(date_time)

