from AlgorithmImports import *
from collections import deque
from datetime import timedelta


class SpyCallCrossoverAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        ).Symbol

        self.spy_option = self.AddOption("SPY", Resolution.Minute)
        self.spy_option.SetFilter(
            lambda universe: universe
            .IncludeWeeklys()
            .Strikes(-100, 100)
            .Expiration(0, 365)
        )

        self.fast_values = deque(maxlen=5)
        self.slow_values = deque(maxlen=20)

        self.minute_bars = {}
        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.expiration_date = None
        self.no_entry_date = None

    def OnData(self, data: Slice):
        current_date = self.Time.date()

        # Handle any unexpected underlying equity position immediately.
        if self.Portfolio[self.spy].Invested:
            self.Debug(
                f"{self.Time}: Unexpected SPY equity position; liquidating it."
            )
            self.Liquidate(self.spy)
            self.no_entry_date = current_date

        # Never intentionally carry an option into or beyond expiration.
        if self.held_symbol is not None and self.Portfolio[self.held_symbol].Invested:
            if (
                self.expiration_date is not None
                and current_date >= self.expiration_date
            ):
                self.Debug(
                    f"{self.Time}: Expiration processing; liquidating "
                    f"{self.held_symbol}."
                )
                self.no_entry_date = current_date
                self._submit_exit("expiration")
            else:
                self._evaluate_held_position(data)

        if self.spy not in data.Bars:
            return

        minute_bar = data.Bars[self.spy]
        bar_start = minute_bar.EndTime - timedelta(minutes=1)

        # Only use regular-session minute bars.
        if not (bar_start.weekday() < 5):
            return

        session_start = bar_start.replace(
            hour=9, minute=30, second=0, microsecond=0
        )
        session_end = bar_start.replace(
            hour=16, minute=0, second=0, microsecond=0
        )

        if bar_start < session_start or bar_start >= session_end:
            return

        bucket_start = bar_start.replace(
            minute=(bar_start.minute // 5) * 5,
            second=0,
            microsecond=0
        )
        bucket = self.minute_bars.setdefault(bucket_start, {})
        bucket[bar_start] = minute_bar

        # The first regular-session bar contains 09:30 through 09:34
        # and closes at 09:35.
        if bar_start.minute % 5 != 4:
            return

        expected_times = [
            bucket_start + timedelta(minutes=i) for i in range(5)
        ]

        if any(timestamp not in bucket for timestamp in expected_times):
            self.Debug(
                f"{self.Time}: Missing SPY minute data; skipping five-minute bar."
            )
            self.minute_bars.pop(bucket_start, None)
            return

        bars = [bucket[timestamp] for timestamp in expected_times]
        consolidated_close = bars[-1].Close
        self.minute_bars.pop(bucket_start, None)

        previous_fast = None
        previous_slow = None

        if len(self.fast_values) >= 5:
            previous_fast = sum(list(self.fast_values)[-5:]) / 5.0
        if len(self.slow_values) >= 20:
            previous_slow = sum(list(self.slow_values)[-20:]) / 20.0

        self.fast_values.append(consolidated_close)
        self.slow_values.append(consolidated_close)

        if len(self.fast_values) < 5 or len(self.slow_values) < 20:
            return

        current_fast = sum(self.fast_values) / 5.0
        current_slow = sum(self.slow_values) / 20.0

        crossover = (
            previous_fast is not None
            and previous_slow is not None
            and previous_fast <= previous_slow
            and current_fast > current_slow
        )

        close_time = bucket_start + timedelta(minutes=5)
        eligible_time = close_time.replace(
            second=0, microsecond=0
        ).time()

        if not (
            crossover
            and eligible_time >= self._time(9, 45)
            and eligible_time <= self._time(14, 30)
        ):
            return

        if current_date == self.no_entry_date:
            return

        if self.held_symbol is not None and self.Portfolio[
            self.held_symbol
        ].Invested:
            return

        if self._entry_order_open():
            return

        self._attempt_entry(data, consolidated_close)

    def _attempt_entry(self, data: Slice, spy_price: float):
        candidates = []

        for chain in data.OptionChains:
            for contract in chain.Contracts.Values:
                if contract.Right != OptionRight.Call:
                    continue

                expiration_date = contract.Expiry.date()
                days_to_expiration = (
                    expiration_date - self.Time.date()
                ).days

                if days_to_expiration < 7:
                    continue

                if contract.Strike < 1.01 * spy_price:
                    continue

                candidates.append(contract)

        if not candidates:
            self.Debug(
                f"{self.Time}: Skipped option selection; no qualifying call."
            )
            return

        nearest_expiration = min(
            contract.Expiry.date() for contract in candidates
        )

        candidates = [
            contract for contract in candidates
            if contract.Expiry.date() == nearest_expiration
        ]

        selected = min(
            candidates,
            key=lambda contract: (
                contract.Strike,
                str(contract.Symbol)
            )
        )

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            f"{self.Time}: Entering 1 SPY call {selected.Symbol}; "
            f"expiration {nearest_expiration}."
        )

    def _evaluate_held_position(self, data: Slice):
        if self.held_symbol is None:
            return

        if not self.Portfolio[self.held_symbol].Invested:
            return

        if self._exit_order_open():
            return

        local_time = self.Time.time()

        if (
            self.expiration_date is not None
            and self._is_pre_expiration_trading_day(
                self.Time.date(), self.expiration_date
            )
            and local_time >= self._time(15, 45)
        ):
            self._submit_exit("pre-expiration time stop")
            return

        if self.entry_price is None:
            return

        option_contract = None
        for chain in data.OptionChains:
            for contract in chain.Contracts.Values:
                if contract.Symbol == self.held_symbol:
                    option_contract = contract
                    break
            if option_contract is not None:
                break

        if option_contract is None:
            return

        bid = option_contract.BidPrice
        ask = option_contract.AskPrice

        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self._submit_exit("50% profit target")

    def _submit_exit(self, reason: str):
        if self.held_symbol is None:
            return

        quantity = -self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        if self._exit_order_open():
            self.exit_ticket.Cancel("Replacing exit order")

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            quantity,
            tag=reason
        )
        self.Debug(
            f"{self.Time}: Exiting {self.held_symbol}; reason: {reason}."
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None:
            if order_event.OrderId == self.entry_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.held_symbol = order_event.Symbol
                    self.entry_price = order_event.FillPrice
                    self.expiration_date = (
                        order_event.Symbol.ID.Date.date()
                    )
                    self.entry_ticket = None
                    self.Debug(
                        f"{self.Time}: Entry filled for "
                        f"{order_event.Symbol} at {order_event.FillPrice}."
                    )
                elif order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid,
                    OrderStatus.Filled
                ):
                    if order_event.Status != OrderStatus.Filled:
                        self.Debug(
                            f"{self.Time}: Entry order did not fill: "
                            f"{order_event.Status}."
                        )
                        self.entry_ticket = None

        if self.exit_ticket is not None:
            if order_event.OrderId == self.exit_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.Debug(
                        f"{self.Time}: Exit filled for "
                        f"{order_event.Symbol} at {order_event.FillPrice}."
                    )
                    self.exit_ticket = None
                    self.held_symbol = None
                    self.entry_price = None
                    self.expiration_date = None
                elif order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid
                ):
                    self.exit_ticket = None

    def OnAssignmentOrderEvent(self, assignment_event: OrderEvent):
        self.Debug(
            f"{self.Time}: Unexpected exercise or assignment for "
            f"{assignment_event.Symbol}; liquidating SPY."
        )
        self.Liquidate(self.spy)
        self.no_entry_date = self.Time.date()

    def _entry_order_open(self):
        return (
            self.entry_ticket is not None
            and self.entry_ticket.Status not in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            )
        )

    def _exit_order_open(self):
        return (
            self.exit_ticket is not None
            and self.exit_ticket.Status not in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            )
        )

    def _is_pre_expiration_trading_day(self, current_date, expiration_date):
        candidate = expiration_date - timedelta(days=1)

        while not self._is_market_date(candidate):
            candidate -= timedelta(days=1)

        return current_date == candidate

    def _is_market_date(self, date_value):
        if date_value.weekday() >= 5:
            return False

        date_time = self.Time.replace(
            year=date_value.year,
            month=date_value.month,
            day=date_value.day,
            hour=0,
            minute=0,
            second=0,
            microsecond=0
        )

        return self.Securities[self.spy].Exchange.Hours.IsDateOpen(date_time)

    @staticmethod
    def _time(hour, minute):
        return __import__("datetime").time(hour, minute)

