                candidates.append(contract)

        if not candidates:
            self.Debug(
                f"{self.Time}: Skipped option selection; no qualifying call."
            )
            return

        nearest_expiration = min(
            contract.Expiry.date() for contract in candidates
        )

        candidates = [
            contract for contract in candidates
            if contract.Expiry.date() == nearest_expiration
        ]

        selected = min(
            candidates,
            key=lambda contract: (
                contract.Strike,
                str(contract.Symbol)
            )
        )

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            f"{self.Time}: Entering 1 SPY call {selected.Symbol}; "
            f"expiration {nearest_expiration}."
        )

    def _evaluate_held_position(self, data: Slice):
        if self.held_symbol is None:
            return

        if not self.Portfolio[self.held_symbol].Invested:
            return

        if self._exit_order_open():
            return

        local_time = self.Time.time()

        if (
            self.expiration_date is not None
            and self._is_pre_expiration_trading_day(
                self.Time.date(), self.expiration_date
            )
            and local_time >= self._time(15, 45)
        ):
            self._submit_exit("pre-expiration time stop")
            return

        if self.entry_price is None:
            return

        option_contract = None
        for chain in data.OptionChains:
            for contract in chain.Contracts.Values:
                if contract.Symbol == self.held_symbol:
                    option_contract = contract
                    break
            if option_contract is not None:
                break

        if option_contract is None:
            return

        bid = option_contract.BidPrice
        ask = option_contract.AskPrice

        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self._submit_exit("50% profit target")

    def _submit_exit(self, reason: str):
        if self.held_symbol is None:
            return

        quantity = -self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        if self._exit_order_open():
            self.exit_ticket.Cancel("Replacing exit order")

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            quantity,
            tag=reason
        )
        self.Debug(
            f"{self.Time}: Exiting {self.held_symbol}; reason: {reason}."
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None:
            if order_event.OrderId == self.entry_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.held_symbol = order_event.Symbol
                    self.entry_price = order_event.FillPrice
                    self.expiration_date = (
                        order_event.Symbol.ID.Date.date()
                    )
                    self.entry_ticket = None
                    self.Debug(
                        f"{self.Time}: Entry filled for "
                        f"{order_event.Symbol} at {order_event.FillPrice}."
                    )
                elif order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid,
                    OrderStatus.Filled
                ):
                    if order_event.Status != OrderStatus.Filled:
                        self.Debug(
                            f"{self.Time}: Entry order did not fill: "
                            f"{order_event.Status}."
                        )
                        self.entry_ticket = None

        if self.exit_ticket is not None:
            if order_event.OrderId == self.exit_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.Debug(
                        f"{self.Time}: Exit filled for "
                        f"{order_event.Symbol} at {order_event.FillPrice}."
                    )
                    self.exit_ticket = None
                    self.held_symbol = None
                    self.entry_price = None
                    self.expiration_date = None
                elif order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid
                ):
                    self.exit_ticket = None

    def OnAssignmentOrderEvent(self, assignment_event: OrderEvent):
        self.Debug(
            f"{self.Time}: Unexpected exercise or assignment for "
            f"{assignment_event.Symbol}; liquidating SPY."
        )
        self.Liquidate(self.spy)
        self.no_entry_date = self.Time.date()

    def _entry_order_open(self):
        return (
            self.entry_ticket is not None
            and self.entry_ticket.Status not in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            )
        )

    def _exit_order_open(self):
        return (
            self.exit_ticket is not None
            and self.exit_ticket.Status not in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            )
        )

    def _is_pre_expiration_trading_day(self, current_date, expiration_date):
        candidate = expiration_date - timedelta(days=1)

        while not self._is_market_date(candidate):
            candidate -= timedelta(days=1)

        return current_date == candidate

    def _is_market_date(self, date_value):
        if date_value.weekday() >= 5:
            return False

        date_time = self.Time.replace(
            year=date_value.year,
            month=date_value.month,
            day=date_value.day,
            hour=0,
            minute=0,
            second=0,
            microsecond=0
        )

        return self.Securities[self.spy].Exchange.Hours.IsDateOpen(date_time)

    @staticmethod
    def _time(hour, minute):
        return __import__("datetime").time(hour, minute)

