            return

        spy_bar = None
        if slice.Bars.ContainsKey(self.spy):
            spy_bar = slice.Bars[self.spy]

        if spy_bar is None or spy_bar.Close <= 0:
            self.Debug("Skipped entry: current SPY price unavailable.")
            return

        contracts = []
        for chain in self._option_chains(slice):
            for contract in self._contracts(chain):
                if contract.Right == OptionRight.Call:
                    expiry_date = contract.Expiry.date()
                    if expiry_date >= today + timedelta(days=7):
                        contracts.append(contract)

        if not contracts:
            self.Debug("Skipped entry: no eligible call contracts.")
            return

        nearest_expiry = min(contract.Expiry.date() for contract in contracts)
        candidates = [
            contract for contract in contracts
            if contract.Expiry.date() == nearest_expiry
            and contract.Strike >= 1.01 * float(spy_bar.Close)
        ]

        if not candidates:
            self.Debug("Skipped entry: no call strike at least 1% OTM.")
            return

        candidates.sort(key=lambda c: (float(c.Strike), str(c.Symbol)))
        selected = candidates[0]

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            "Entry submitted: {} expiring {} strike {:.2f}".format(
                selected.Symbol, nearest_expiry, selected.Strike
            )
        )

    def OnOrderEvent(self, order_event):
        if order_event.Status == OrderStatus.Filled:
            if (
                self.entry_ticket is not None
                and order_event.OrderId == self.entry_ticket.OrderId
            ):
                self.held_symbol = order_event.Symbol
                self.entry_price = float(order_event.FillPrice)
                self.Debug(
                    "Entry filled: {} at {:.4f}".format(
                        self.held_symbol, self.entry_price
                    )
                )
                self.entry_ticket = None

            elif (
                self.exit_ticket is not None
                and order_event.OrderId == self.exit_ticket.OrderId
            ):
                self.Debug(
                    "Exit filled: {} at {:.4f}".format(
                        order_event.Symbol, order_event.FillPrice
                    )
                )
                self.exit_ticket = None
                self.held_symbol = None
                self.entry_price = None

        elif (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
            and order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.None
            )
        ):
            self.entry_ticket = None

        if (
            getattr(order_event, "IsAssignment", False)
            or getattr(order_event, "IsExercise", False)
        ):
            self.Debug("Unexpected option exercise or assignment detected.")
            self._handle_unexpected_equity_position()

    def _profit_target_reached(self, slice):
        if self.held_symbol is None or self.entry_price is None:
            return False

        if not slice.QuoteBars.ContainsKey(self.held_symbol):
            return False

        quote = slice.QuoteBars[self.held_symbol]
        bid = float(quote.Bid.Close)
        ask = float(quote.Ask.Close)

        if bid <= 0 or ask <= 0:
            return False

        midpoint = (bid + ask) / 2.0
        return midpoint >= 1.50 * self.entry_price

    def _submit_exit(self, reason):
        if self.held_symbol is None:
            return

        if self.exit_ticket is not None and self._is_open(self.exit_ticket.Status):
            return

        if self.entry_ticket is not None and self._is_open(self.entry_ticket.Status):
            self.entry_ticket.Cancel("Canceling entry before exit")
            self.entry_ticket = None

        holding = self.Portfolio[self.held_symbol]
        quantity = int(holding.Quantity)

        if quantity == 0:
            return

        if self.exit_ticket is not None and self._is_open(self.exit_ticket.Status):
            self.exit_ticket.Cancel("Replacing open exit order")

        self.exit_ticket = self.MarketOrder(self.held_symbol, -quantity)
        self.Debug("Exit submitted: {}".format(reason))

    def _process_expiration(self, today):
        if self.held_symbol is None:
            return

        expiry_date = self.held_symbol.ID.Date.date()

        if today >= expiry_date:
            self.no_entry_date = today
            if self.entry_ticket is not None:
                self.entry_ticket.Cancel("Expiration processing")
                self.entry_ticket = None
            self._submit_exit("expiration protection")
        elif self._time_stop_reached(today):
            self._submit_exit("expiration time stop")

    def _time_stop_reached(self, today):
        if self.held_symbol is None or self.Time.time() < time(15, 45):
            return False

        expiry_date = self.held_symbol.ID.Date.date()
        if today >= expiry_date:
            return False

        try:
            days = self.TradingCalendar.GetDaysByType(
                TradingDayType.BusinessDay,
                expiry_date - timedelta(days=14),
                expiry_date
            )
            preceding = [
                day.Date.date() for day in days
                if day.Date.date() < expiry_date
            ]
            return bool(preceding) and today == max(preceding)
        except Exception:
            return today == expiry_date - timedelta(days=1)

    def _handle_unexpected_equity_position(self):
        quantity = int(self.Portfolio[self.spy].Quantity)
        if quantity != 0:
            self.no_entry_date = self.Time.date()
            self.Debug("Unexpected SPY equity position; liquidating immediately.")
            self.MarketOrder(self.spy, -quantity)

    @staticmethod
    def _is_open(status):
        return status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
        )

    @staticmethod
    def _option_chains(slice):
        if not slice.OptionChains:
            return []

        try:
            return list(slice.OptionChains.Values)
        except Exception:
            return list(slice.OptionChains)

    @staticmethod
    def _contracts(chain):
        try:
            return list(chain.Contracts.Values)
        except Exception:
            try:
                return list(chain)
            except Exception:
                return []

