        self.exit_ticket = None
        self.entry_price = None
        self.held_option = None
        self.no_entry_date = None

    def OnData(self, slice: Slice):
        current_date = self.Time.date()

        # Expiration-day protection begins at the start of the algorithm day.
        if self.held_option is not None:
            expiry_date = self.held_option.ID.Date.date()
            if current_date >= expiry_date:
                self.no_entry_date = current_date
                if self._ticket_is_open(self.entry_ticket):
                    self.entry_ticket.Cancel("Expiration-day protection")
                if self._has_option_position():
                    self._submit_exit("Expiration-day liquidation")

        # Immediately liquidate any unexpected SPY equity position.
        if self.Portfolio[self.spy_symbol].Invested:
            self.Debug("Unexpected SPY equity position detected; liquidating.")
            self.MarketOrder(
                self.spy_symbol,
                -self.Portfolio[self.spy_symbol].Quantity,
                tag="Unexpected exercise or assignment handling",
            )

        # Evaluate the held option on every minute Slice.
        if self._has_option_position() and self.held_option is not None:
            self._evaluate_profit_target(slice)

            expiry_date = self.held_option.ID.Date.date()
            previous_trading_day = self._previous_trading_day(expiry_date)

            if (
                current_date == previous_trading_day
                and self.Time.hour == 15
                and self.Time.minute == 45
            ):
                self.no_entry_date = current_date
                self._submit_exit("Pre-expiration time stop")

        # Build five-minute bars from actual SPY minute bars only.
        if slice.Bars.ContainsKey(self.spy_symbol):
            minute_bar = slice.Bars[self.spy_symbol]
            self._process_minute_bar(minute_bar)

    def _process_minute_bar(self, minute_bar: TradeBar):
        end_time = minute_bar.EndTime
        local_time = end_time.time()

        if local_time < datetime.strptime("09:30", "%H:%M").time():
            return
        if local_time > datetime.strptime("16:00", "%H:%M").time():
            return

        minute = end_time.minute
        bucket_minute = ((minute + 4) // 5) * 5

        if bucket_minute >= 60:
            bucket_end = end_time.replace(
                hour=end_time.hour + 1, minute=0, second=0, microsecond=0
            )
        else:
            bucket_end = end_time.replace(
                minute=bucket_minute, second=0, microsecond=0
            )

        if self.current_bucket_end is None:
            self.current_bucket_end = bucket_end
            self.current_bucket_close = minute_bar.Close
        elif bucket_end != self.current_bucket_end:
            self._complete_five_minute_bar(
                self.current_bucket_end,
                self.current_bucket_close,
            )
            self.current_bucket_end = bucket_end
            self.current_bucket_close = minute_bar.Close
        else:
            self.current_bucket_close = minute_bar.Close

        if end_time >= self.current_bucket_end:
            completed_end = self.current_bucket_end
            completed_close = self.current_bucket_close
            self.current_bucket_end = None
            self.current_bucket_close = None
            self._complete_five_minute_bar(completed_end, completed_close)

    def _complete_five_minute_bar(self, bar_end: datetime, close: float):
        self.slow_closes.append(close)
        self.fast_closes.append(close)

        if len(self.slow_closes) > 20:
            self.slow_closes.pop(0)
        if len(self.fast_closes) > 5:
            self.fast_closes.pop(0)

        current_fast = None
        current_slow = None

        if len(self.fast_closes) == 5:
            current_fast = sum(self.fast_closes) / 5.0
        if len(self.slow_closes) == 20:
            current_slow = sum(self.slow_closes) / 20.0

        crossover = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and current_fast is not None
            and current_slow is not None
            and self.previous_fast <= self.previous_slow
            and current_fast > current_slow
        )

        self.previous_fast = current_fast
        self.previous_slow = current_slow

        if not crossover:
            return

        bar_time = bar_end.time()
        eligible_start = datetime.strptime("09:45", "%H:%M").time()
        eligible_end = datetime.strptime("14:30", "%H:%M").time()

        if eligible_start <= bar_time <= eligible_end:
            self._try_enter()

    def _try_enter(self):
        current_date = self.Time.date()

        if self.no_entry_date == current_date:
            return
        if self._has_option_position():
            return
        if self._ticket_is_open(self.entry_ticket):
            return

        underlying_price = self.Securities[self.spy_symbol].Price
        if underlying_price <= 0:
            self.Debug("Skipped selection: invalid SPY price.")
            return

        chain = None
        if self.option_symbol in self.CurrentSlice.OptionChains:
            chain = self.CurrentSlice.OptionChains[self.option_symbol]

        if chain is None:
            self.Debug("Skipped selection: option chain unavailable.")
            return

        minimum_expiry = current_date + timedelta(days=7)
        eligible_contracts = [
            contract
            for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() >= minimum_expiry
        ]

        if not eligible_contracts:
            self.Debug("Skipped selection: no eligible call contracts.")
            return

        nearest_expiry = min(
            contract.Expiry.date() for contract in eligible_contracts
        )

        strike_floor = underlying_price * 1.01
        candidates = [
            contract
            for contract in eligible_contracts
            if contract.Expiry.date() == nearest_expiry
            and contract.Strike >= strike_floor
        ]

        if not candidates:
            self.Debug("Skipped selection: no call strike at least 1% OTM.")
            return

        selected = min(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol)),
        )

        self.held_option = selected.Symbol
        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover entry",
        )

        self.Debug(
            f"Entry submitted: {selected.Symbol}, "
            f"expiry {selected.Expiry.date()}, strike {selected.Strike}."
        )

    def _evaluate_profit_target(self, slice: Slice):
        contract = self._find_contract(slice, self.held_option)
        if contract is None:
            return

        bid = contract.BidPrice
        ask = contract.AskPrice

        if bid <= 0 or ask <= 0:
            return
        if self.entry_price is None:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self._submit_exit("50% profit target")

    def _submit_exit(self, tag: str):
        if not self._has_option_position() or self.held_option is None:
            return
        if self._ticket_is_open(self.exit_ticket):
            return

        if self.exit_ticket is not None:
            self.exit_ticket.Cancel("Replacing prior exit order")

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity == 0:
            return

        self.exit_ticket = self.MarketOrder(
            self.held_option,
            -quantity,
            tag=tag,
