        if len(closes) != 5:
            return

        current_close = closes[-1]
        previous_fast = None
        previous_slow = None

        if len(self.closes) >= 20:
            previous_fast = sum(list(self.closes)[-5:]) / 5.0
            previous_slow = sum(self.closes) / 20.0

        self.closes.append(current_close)

        if len(self.closes) < 20:
            return

        current_fast = sum(list(self.closes)[-5:]) / 5.0
        current_slow = sum(self.closes) / 20.0

        bullish_cross = (
            previous_fast is not None
            and previous_slow is not None
            and previous_fast <= previous_slow
            and current_fast > current_slow
        )

        if not bullish_cross:
            return

        if not (time(9, 45) <= bucket_end.time() <= time(14, 30)):
            return

        if self.unexpected_equity_date == self.Time.date():
            return

        if self.held_symbol is not None:
            return

        if self.entry_ticket is not None and not self._ticket_finished(self.entry_ticket):
            return

        if self.exit_ticket is not None and not self._ticket_finished(self.exit_ticket):
            return

        self._enter_from_chain(data, current_close)

    def _enter_from_chain(self, data: Slice, spy_price: float):
        chain = data.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug("Skipped entry: option chain unavailable.")
            return

        minimum_expiry = self.Time.date() + timedelta(days=7)
        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expirations:
            self.Debug("Skipped entry: no expiration at least seven days out.")
            return

        expiry_date = expirations[0]
        threshold = spy_price * 1.01

        candidates = [
            contract for contract in chain
            if contract.Expiry.date() == expiry_date
            and contract.Right == OptionRight.Call
            and contract.Strike >= threshold
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call strike.")
            return

        candidates.sort(key=lambda contract: (contract.Strike, str(contract.Symbol)))
        selected = candidates[0]

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )
        self.entry_value = 0.0
        self.entry_quantity = 0
        self.entry_price = None
        self.held_symbol = selected.Symbol

        self.Debug(
            f"Entry submitted: {selected.Symbol}, "
            f"expiry {expiry_date}, strike {selected.Strike}"
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                quantity = abs(order_event.FillQuantity)
                self.entry_value += quantity * float(order_event.FillPrice)
                self.entry_quantity += quantity

                if self.entry_quantity > 0:
                    self.entry_price = self.entry_value / self.entry_quantity

                self.Debug(
                    f"Entry filled: {self.held_symbol}, "
                    f"price {order_event.FillPrice}"
                )

            if order_event.Status in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.PartiallyFilled
            ) and self.entry_quantity > 0:
                self.entry_ticket = None

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(f"Exit filled: {self.held_symbol}")

            if order_event.Status in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                if self.held_symbol is not None:
                    holding = self.Portfolio[self.held_symbol]
                    if not holding.Invested or holding.Quantity == 0:
                        self.held_symbol = None
                        self.entry_price = None
                        self.entry_value = 0.0
                        self.entry_quantity = 0
                self.exit_ticket = None

        if getattr(order_event, "IsAssignment", False):
            self._handle_unexpected_equity_position()

    def OnAssignmentOrder(self, assignment_event: AssignmentOrderEvent):
        self._handle_unexpected_equity_position()

    def _process_expiration_and_exits(self, data: Slice):
        if self.held_symbol is None:
            return

        holding = self.Portfolio[self.held_symbol]
        if not holding.Invested or holding.Quantity <= 0:
            return

        expiry_date = self.Securities[self.held_symbol].Expiry.date()
        current_date = self.Time.date()

        if current_date >= expiry_date:
            self.expiration_processing_date = current_date
            self._submit_exit("Expiration protection")
            return

        if (
            self.Time.hour == 15
            and self.Time.minute == 45
            and self._is_immediately_preceding_trading_day(current_date, expiry_date)
        ):
            self._submit_exit("Expiration-eve time stop")
            return

        if self.exit_ticket is not None and not self._ticket_finished(self.exit_ticket):
            return

        if self.entry_price is None or self.entry_price <= 0:
            return

        quote = self._held_quote(data)
        if quote is None:
            return

        bid, ask = quote
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self._submit_exit("50 percent profit target")

    def _submit_exit(self, reason: str):
        if self.held_symbol is None:
            return

        holding = self.Portfolio[self.held_symbol]
        quantity = holding.Quantity
        if quantity <= 0:
            return

        if self.exit_ticket is not None and not self._ticket_finished(self.exit_ticket):
            self.exit_ticket.Cancel("Replacing exit order")

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )
        self.Debug(f"Exit submitted: {self.held_symbol} ({reason})")

    def _held_quote(self, data: Slice):
        chain = data.OptionChains.get(self.option_symbol)
        if chain is not None:
            for contract in chain:
                if contract.Symbol == self.held_symbol:
                    return float(contract.BidPrice), float(contract.AskPrice)

        quote_bar = data.QuoteBars.get(self.held_symbol)
        if quote_bar is not None:
            return float(quote_bar.Bid.Close), float(quote_bar.Ask.Close)

        return None

    def _handle_unexpected_equity_position(self):
        holding = self.Portfolio[self.spy]
        if holding.Quantity == 0:
            return

        self.unexpected_equity_date = self.Time.date()
        self.Debug(
            f"Unexpected SPY equity position detected "
            f"({holding.Quantity}); liquidating."
        )
        self.MarketOrder(
            self.spy,
            -holding.Quantity,
            tag="Unexpected exercise or assignment handling"
        )

    def _is_regular_session_minute(self, local_time: datetime) -> bool:
        current = local_time.time()
        return time(9, 31) <= current <= time(16, 0)

    def _bucket_end(self, local_time: datetime) -> datetime:
        minute_offset = local_time.minute - 30
        end_offset = ((minute_offset + 4) // 5) * 5
        return local_time.replace(
            minute=30 + end_offset,
            second=0,
            microsecond=0
        )

    def _is_immediately_preceding_trading_day(
        self,
        current_date,
        expiration_date
    ) -> bool:
        if current_date >= expiration_date:
            return False

        date = current_date + timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while date < expiration_date:
            if exchange_hours.IsDateOpen(date):
                return False
            date += timedelta(days=1)

        return date == expiration_date and exchange_hours.IsDateOpen(date)

    def _ticket_finished(self, ticket) -> bool:
        return ticket.Status in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        )

