from AlgorithmImports import *
from collections import OrderedDict
from datetime import timedelta


class SpyFiveMinuteCallStrategy(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity("SPY", Resolution.Minute)
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy_symbol = self.spy.Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 365)
        )

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self.aggregate_bucket_end = None
        self.aggregate_bars = OrderedDict()

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.expiration_block_date = None

    def OnData(self, slice: Slice):
        current_date = self.Time.date()

        self._process_expiration()
        self._process_assignment_equity()

        signal = self._update_five_minute_bar(slice)

        self._evaluate_profit_target(slice)
        self._evaluate_time_stop()

        if signal and self._eligible_for_entry(current_date):
            self._enter_from_chain(slice)

    def _update_five_minute_bar(self, slice):
        bar = slice.Bars.get(self.spy_symbol)
        if bar is None:
            return False

        end_time = bar.EndTime
        if end_time.tzinfo is not None:
            end_time = end_time.replace(tzinfo=None)

        if end_time.time() < datetime.time(9, 30) or end_time.time() > datetime.time(16, 0):
            return False

        minute = end_time.replace(second=0, microsecond=0)
        remainder = minute.minute % 5
        bucket_end = minute + timedelta(minutes=(5 - remainder) % 5)
        bucket_start = bucket_end - timedelta(minutes=5)

        if self.aggregate_bucket_end != bucket_end:
            self.aggregate_bucket_end = bucket_end
            self.aggregate_bars = OrderedDict()

        if minute < bucket_start or minute > bucket_end:
            return False

        self.aggregate_bars[minute] = bar

        if minute != bucket_end or len(self.aggregate_bars) < 5:
            return False

        expected_times = [
            bucket_start + timedelta(minutes=i)
            for i in range(1, 6)
        ]

        if list(self.aggregate_bars.keys()) != expected_times:
            self.aggregate_bars = OrderedDict()
            return False

        completed_close = list(self.aggregate_bars.values())[-1].Close
        previous_fast = self.fast.Current.Value if self.fast.IsReady else None
        previous_slow = self.slow.Current.Value if self.slow.IsReady else None

        self.fast.Update(bucket_end, completed_close)
        self.slow.Update(bucket_end, completed_close)
        self.aggregate_bars = OrderedDict()

        if not self.fast.IsReady or not self.slow.IsReady:
            return False

        if previous_fast is None or previous_slow is None:
            return False

        crossover = (
            previous_fast <= previous_slow
            and self.fast.Current.Value > self.slow.Current.Value
        )

        bar_end_time = bucket_end.time()
        return (
            crossover
            and datetime.time(9, 45) <= bar_end_time <= datetime.time(14, 30)
        )

    def _eligible_for_entry(self, current_date):
        if self.held_symbol is not None:
            return False

        if self._entry_order_open():
            return False

        if self.expiration_block_date == current_date:
            return False

        return True

    def _enter_from_chain(self, slice: Slice):
        spy_bar = slice.Bars.get(self.spy_symbol)
        if spy_bar is None or spy_bar.Close <= 0:
            self.Debug("Skipped selection: unavailable SPY price.")
            return

        chains = list(slice.OptionChains.Values)
        if not chains:
            self.Debug("Skipped selection: no option chain.")
            return

        current_date = self.Time.date()
        minimum_expiry = current_date + timedelta(days=7)

        contracts = []
        for chain in chains:
            for contract in chain:
                expiry = contract.Expiry.date()
                if (
                    contract.Right == OptionRight.Call
                    and expiry >= minimum_expiry
                ):
                    contracts.append(contract)

        if not contracts:
            self.Debug("Skipped selection: no eligible call contracts.")
            return

        nearest_expiry = min(contract.Expiry.date() for contract in contracts)
        target_strike = 1.01 * float(spy_bar.Close)

        eligible = [
            contract for contract in contracts
            if contract.Expiry.date() == nearest_expiry
            and float(contract.Strike) >= target_strike
        ]

        if not eligible:
            self.Debug("Skipped selection: no call strike at least 1% OTM.")
            return

        selected = sorted(
            eligible,
            key=lambda contract: (float(contract.Strike), str(contract.Symbol))
        )[0]

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )
        self.Debug(
            f"Entry submitted: {selected.Symbol} "
            f"strike={selected.Strike} expiry={selected.Expiry.date()}"
        )

    def _evaluate_profit_target(self, slice: Slice):
        if self.held_symbol is None or self.entry_price is None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity <= 0 or self._exit_order_open():
            return

        quote = slice.QuoteBars.get(self.held_symbol)
        if quote is None or quote.Bid is None or quote.Ask is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close
        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2
        if midpoint >= 1.50 * self.entry_price:
            self._cancel_open_exit()
            self.exit_ticket = self.MarketOrder(
                self.held_symbol,
                -quantity,
                tag="50% option profit target"
            )
            self.Debug(
                f"Exit submitted: profit target on {self.held_symbol}, "
                f"midpoint={midpoint}"
            )

    def _evaluate_time_stop(self):
        if self.held_symbol is None or self._exit_order_open():
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity <= 0:
            return

        expiry_date = self.held_symbol.ID.Date.date()
        previous_trading_day = self._previous_trading_day(expiry_date)

        if (
            self.Time.date() == previous_trading_day
            and self.Time.time() >= datetime.time(15, 45)
        ):
            self.exit_ticket = self.MarketOrder(
                self.held_symbol,
                -quantity,
                tag="Expiration-eve time stop"
            )
            self.Debug(f"Exit submitted: expiration-eve time stop on {self.held_symbol}")

    def _process_expiration(self):
        if self.held_symbol is None:
            return

        expiry_date = self.held_symbol.ID.Date.date()
        if self.Time.date() < expiry_date:
            return

        self.expiration_block_date = self.Time.date()
        quantity = self.Portfolio[self.held_symbol].Quantity

        if quantity > 0 and not self._exit_order_open():
            self.exit_ticket = self.MarketOrder(
                self.held_symbol,
                -quantity,
                tag="Emergency expiration liquidation"
            )
            self.Debug(
                f"Exit submitted: unexpected position at expiration for "
                f"{self.held_symbol}"
            )

    def _process_assignment_equity(self):
        quantity = self.Portfolio[self.spy_symbol].Quantity
        if quantity != 0:
            self.Debug(
                f"Unexpected exercise or assignment handling: "
                f"liquidating SPY quantity {quantity}"
            )
            self.MarketOrder(
                self.spy_symbol,
                -quantity,
                tag="Unexpected exercise or assignment liquidation"
            )

    def OnAssignmentOrderEvent(self, assignment_event):
        self.Debug("Unexpected assignment event received.")
        self._liquidate_unexpected_spy_position()

    def OnExerciseOrder(self, exercise_event):
        self.Debug("Unexpected exercise event received.")
        self._liquidate_unexpected_spy_position()

    def _liquidate_unexpected_spy_position(self):
        quantity = self.Portfolio[self.spy_symbol].Quantity
        if quantity != 0:
            self.MarketOrder(
                self.spy_symbol,
                -quantity,
                tag="Unexpected exercise or assignment liquidation"
            )

    def OnOrderEvent(self, order_event):
        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.FillQuantity > 0:
                self.held_symbol = self.entry_ticket.Symbol
                self.entry_price = order_event.FillPrice
                self.Debug(
                    f"Entry filled: {self.held_symbol} "
                    f"price={self.entry_price}"
                )

            if order_event.Status in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.entry_ticket = None

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
            and order_event.Status == OrderStatus.Filled
        ):
            self.Debug(f"Exit filled: {self.held_symbol}")
            self.exit_ticket = None
            self.held_symbol = None
            self.entry_price = None

    def _entry_order_open(self):
        return (
            self.entry_ticket is not None
            and self.entry_ticket.Status in (
                OrderStatus.New,
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled
            )
        )

    def _exit_order_open(self):
        return (
            self.exit_ticket is not None
            and self.exit_ticket.Status in (
                OrderStatus.New,
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled
            )
        )

    def _cancel_open_exit(self):
        if self._exit_order_open():
            self.exit_ticket.Cancel("Canceled by profit-target liquidation")

    def _previous_trading_day(self, date):
        candidate = date - timedelta(days=1)
        while not self.spy.Exchange.Hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)
        return candidate


