class SpyLongCallCrossover(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        self.spy = self.AddEquity("SPY", Resolution.Minute)
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 365)
        )

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self._previous_fast = None
        self._previous_slow = None
        self._pending_signal = None

        self._entry_ticket = None
        self._held_option = None
        self._entry_price = None
        self._exit_ticket = None
        self._blocked_entry_dates = set()

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.DataConsolidated += self._on_five_minute_bar
        self.SubscriptionManager.AddConsolidator(self.spy.Symbol, consolidator)

    def _on_five_minute_bar(self, sender, bar):
        end_time = bar.EndTime
        end_clock = end_time.time()

        # Accept only bars aligned to New York five-minute clock boundaries.
        if end_clock.minute % 5 != 0 or end_clock.second != 0:
            return

        # Do not use an incomplete or abnormally spanning consolidated bar.
        if bar.EndTime - bar.Time != timedelta(minutes=5):
            return

        self._previous_fast = self.fast.Current.Value if self.fast.IsReady else None
        self._previous_slow = self.slow.Current.Value if self.slow.IsReady else None

        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        if not self.fast.IsReady or not self.slow.IsReady:
            return

        if self._previous_fast is None or self._previous_slow is None:
            return

        eligible_time = (
            end_clock >= datetime.strptime("09:45", "%H:%M").time()
            and end_clock <= datetime.strptime("14:30", "%H:%M").time()
        )

        bullish_cross = (
            self._previous_fast <= self._previous_slow
            and self.fast.Current.Value > self.slow.Current.Value
        )

        if eligible_time and bullish_cross:
            self._pending_signal = (end_time.date(), float(bar.Close))

    def OnData(self, slice):
        self._handle_unexpected_spy_position()

        if self._held_option is not None:
            self._manage_open_position(slice)

        if self._pending_signal is not None:
            signal_date, spy_price = self._pending_signal
            self._pending_signal = None
            self._try_enter(slice, signal_date, spy_price)

    def _try_enter(self, slice, signal_date, spy_price):
        if signal_date in self._blocked_entry_dates:
            return

        if self._held_option is not None and self.Portfolio[self._held_option].Quantity > 0:
            return

        if self._is_open(self._entry_ticket):
            return

        candidates = []

        for chain in slice.OptionChains.Values:
            for contract in chain.Contracts.Values:
                if contract.Right != OptionRight.Call:
                    continue
                if contract.Expiry.date() < signal_date + timedelta(days=7):
                    continue
                if contract.Strike < 1.01 * spy_price:
                    continue
                candidates.append(contract)

        if not candidates:
            self.Debug(
                "Skipped option selection: no qualifying SPY call "
                f"on {signal_date}."
            )
            return

        nearest_expiry = min(contract.Expiry.date() for contract in candidates)
        candidates = [
            contract for contract in candidates
            if contract.Expiry.date() == nearest_expiry
        ]

        selected = min(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self._held_option = selected.Symbol
        self._entry_price = None
        self._exit_ticket = None
        self._entry_ticket = self.MarketOrder(self._held_option, 1)

        self.Debug(
            f"Entry submitted: {self._held_option} "
            f"at SPY price {spy_price:.2f}."
        )

    def _manage_open_position(self, slice):
        symbol = self._held_option

        if self.Portfolio[symbol].Quantity <= 0:
            return

        expiry_date = self.Securities[symbol].Symbol.ID.Date.date()
        current_date = self.Time.date()

        if current_date >= expiry_date:
            self._blocked_entry_dates.add(current_date)
            self._submit_exit("expiration processing")
            return

        previous_trading_day = self._previous_trading_day(expiry_date)

        if (
            current_date == previous_trading_day
            and self.Time.hour == 15
            and self.Time.minute >= 45
        ):
            self._submit_exit("expiration time stop")
            return

        if self._entry_price is None or self._is_open(self._exit_ticket):
            return

        quote = self._get_current_option_quote(slice, symbol)
        if quote is None:
            return

        bid, ask = quote
        midpoint = (bid + ask) / 2.0

        if midpoint >= 1.50 * self._entry_price:
            self._submit_exit("50% profit target")

    def _get_current_option_quote(self, slice, symbol):
        for chain in slice.OptionChains.Values:
            contract = chain.Contracts.get(symbol)
            if contract is not None:
                bid = float(contract.BidPrice)
                ask = float(contract.AskPrice)
                if bid > 0 and ask > 0:
                    return bid, ask
                return None
        return None

    def _submit_exit(self, reason):
        if self._held_option is None:
            return

        quantity = self.Portfolio[self._held_option].Quantity
        if quantity <= 0 or self._is_open(self._exit_ticket):
            return

        self._cancel_open_exit_orders(self._held_option)
        self._exit_ticket = self.MarketOrder(
            self._held_option,
            -quantity
        )
        self.Debug(
            f"Exit submitted ({reason}): {self._held_option}, "
            f"quantity {quantity}."
        )

    def _cancel_open_exit_orders(self, symbol):
        for order in self.Transactions.GetOpenOrders(symbol):
            if self._entry_ticket is None or order.Id != self._entry_ticket.OrderId:
                self.Transactions.CancelOrder(order.Id)

    def OnOrderEvent(self, order_event):
        if (
            self._entry_ticket is not None
            and order_event.OrderId == self._entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self._entry_price = float(order_event.FillPrice)
                self.Debug(
                    f"Entry filled: {order_event.Symbol}, "
                    f"price {self._entry_price:.4f}."
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.PartiallyFilled,
            ):
                if order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                    self.Debug(
                        f"Skipped entry: order {order_event.Status}."
                    )
                    self._entry_ticket = None
                    self._held_option = None
                    self._entry_price = None
            return

        if (
            self._exit_ticket is not None
            and order_event.OrderId == self._exit_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    f"Exit filled: {order_event.Symbol}, "
                    f"price {float(order_event.FillPrice):.4f}."
                )
                self._held_option = None
                self._entry_price = None
                self._exit_ticket = None
                self._entry_ticket = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
            ):
                self._exit_ticket = None
            return

        if self._is_assignment_event(order_event):
            self._blocked_entry_dates.add(self.Time.date())
            self.Debug(
                f"Unexpected exercise or assignment handling for "
                f"{order_event.Symbol}."
            )
            self._liquidate_spy_position()

    def _handle_unexpected_spy_position(self):
        if self.Portfolio[self.spy.Symbol].Quantity != 0:
            self._blocked_entry_dates.add(self.Time.date())
            self.Debug(
                "Unexpected SPY equity position detected; liquidating it."
            )
            self._liquidate_spy_position()

    def _liquidate_spy_position(self):
        quantity = self.Portfolio[self.spy.Symbol].Quantity
        if quantity != 0:
            self.MarketOrder(self.spy.Symbol, -quantity)

    def _previous_trading_day(self, date_value):
        candidate = date_value - timedelta(days=1)
        hours = self.Securities[self.spy.Symbol].Exchange.Hours

        while not hours.IsDateOpen(
            datetime(candidate.year, candidate.month, candidate.day)
        ):
            candidate -= timedelta(days=1)

        return candidate

    @staticmethod
    def _is_open(ticket):
        if ticket is None:
            return False

        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending,
        )

    @staticmethod
    def _is_assignment_event(order_event):
        if bool(getattr(order_event, "IsAssignment", False)):
            return True

        message = str(getattr(order_event, "Message", "")).lower()
        return "assign" in message or "exercis" in message

