from AlgorithmImports import *
from datetime import datetime, timedelta


class SpyCallCrossoverAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw,
            fillForward=False
        ).Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-1000, 1000)
                .Expiration(0, 365)
        )
        self.option_symbol = option.Symbol

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self.consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self.consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, self.consolidator)

        self.current_slice = None
        self.pending_entry_check = False
        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.no_entries_today = False
        self.exercise_or_assignment_seen = False

    def OnFiveMinuteBar(self, sender, bar):
        if self.fast.IsReady and self.slow.IsReady:
            previous_fast = self.fast.Current.Value
            previous_slow = self.slow.Current.Value
        else:
            previous_fast = None
            previous_slow = None

        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        if previous_fast is None or not self.fast.IsReady or not self.slow.IsReady:
            return

        bar_time = bar.EndTime
        eligible_time = (
            bar_time.hour > 9 or
            (bar_time.hour == 9 and bar_time.minute >= 45)
        ) and (
            bar_time.hour < 14 or
            (bar_time.hour == 14 and bar_time.minute <= 30)
        )

        if (
            eligible_time and
            previous_fast <= previous_slow and
            self.fast.Current.Value > self.slow.Current.Value
        ):
            self.pending_entry_check = True

    def OnData(self, slice: Slice):
        self.current_slice = slice
        today = self.Time.date()
        self.no_entries_today = False

        self.HandleExerciseOrAssignment()
        self.HandleExpirationProcessing(today)
        self.HandleMinuteExits(today)

        if self.pending_entry_check:
            self.pending_entry_check = False
            self.TryEnter(slice, today)

    def HandleExerciseOrAssignment(self):
        if not self.exercise_or_assignment_seen:
            return

        quantity = self.Portfolio[self.spy].Quantity
        if quantity != 0:
            self.Debug("Unexpected exercise or assignment: liquidating SPY equity.")
            self.MarketOrder(self.spy, -quantity)

        self.exercise_or_assignment_seen = False

    def HandleExpirationProcessing(self, today):
        if self.held_symbol is None:
            return

        expiry = self.held_symbol.ID.Date.date()

        if today >= expiry:
            self.no_entries_today = True
            if self.entry_ticket is not None and self.entry_ticket.Status.IsOpen():
                self.entry_ticket.Cancel("Expiration processing")
            self.SubmitOptionLiquidation("expiration processing")

    def HandleMinuteExits(self, today):
        if self.held_symbol is None:
            return

        expiry = self.held_symbol.ID.Date.date()

        if (
            today < expiry and
            self.IsTradingDayImmediatelyBeforeExpiry(today, expiry) and
            self.Time.hour == 15 and
            self.Time.minute >= 45
        ):
            self.SubmitOptionLiquidation("expiration time stop")
            return

