        self.option_symbol = option.Symbol
        option.SetFilter(
            lambda universe: universe
                .CallsOnly()
                .IncludeWeeklys()
                .Strikes(-1000, 1000)
                .Expiration(0, 365)
        )

        self.fast_closes = []
        self.slow_closes = []
        self.pending_signal = False

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_fill_price = None
        self.no_entry_today = False

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, consolidator)

        self.Schedule.On(
            self.DateRules.EveryDay(self.spy),
            self.TimeRules.At(0, 1),
            self.ProcessExpiration
        )

    def OnFiveMinuteBar(self, sender, bar):
        bar_time = bar.EndTime.time()

        if bar_time < time(9, 35) or bar_time > time(16, 0):
            return

        previous_fast = None
        previous_slow = None

        if len(self.fast_closes) >= 5:
            previous_fast = sum(self.fast_closes[-5:]) / 5.0

        if len(self.slow_closes) >= 20:
            previous_slow = sum(self.slow_closes[-20:]) / 20.0

        self.fast_closes.append(float(bar.Close))
        self.slow_closes.append(float(bar.Close))

        if len(self.fast_closes) > 20:
            self.fast_closes.pop(0)
        if len(self.slow_closes) > 20:
            self.slow_closes.pop(0)

        if len(self.fast_closes) < 5 or len(self.slow_closes) < 20:
            return

        current_fast = sum(self.fast_closes[-5:]) / 5.0
        current_slow = sum(self.slow_closes[-20:]) / 20.0

        eligible_time = time(9, 45) <= bar_time <= time(14, 30)

        if (
            eligible_time
            and previous_fast is not None
            and previous_slow is not None
            and previous_fast <= previous_slow
            and current_fast > current_slow
        ):
            self.pending_signal = True

    def OnData(self, slice):
        self.HandleUnexpectedEquityPosition()

        if self.held_symbol is not None:
            self.EvaluateExit(slice)

        if self.pending_signal:
            self.pending_signal = False
            self.TryEnter(slice)

    def TryEnter(self, slice):
        if self.no_entry_today:
            return

        if self.held_symbol is not None:
            return

        if self.entry_ticket is not None and self.IsOpen(self.entry_ticket):
            return

        spy_bar = slice.Bars.get(self.spy)
        if spy_bar is None or spy_bar.Close <= 0:
            self.Debug("Skipped call selection: current SPY price unavailable.")
            return

        current_price = float(spy_bar.Close)
        today = self.Time.date()
        minimum_expiry = today + timedelta(days=7)

        candidates = []

        for chain in slice.OptionChains.Values:
            for contract in chain.Contracts.Values:
                if contract.Right != OptionRight.Call:
                    continue

                expiry_date = contract.Expiry.date()

                if expiry_date < minimum_expiry:
                    continue

                if contract.Strike >= 1.01 * current_price:
                    candidates.append(contract)

        if not candidates:
            self.Debug("Skipped call selection: no eligible SPY call contract.")
            return

        nearest_expiry = min(contract.Expiry.date() for contract in candidates)
        candidates = [
            contract for contract in candidates
            if contract.Expiry.date() == nearest_expiry
        ]

        selected = min(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish crossover call entry"
        )

        self.Debug(
            "Call entry submitted: {0}, strike={1}, expiry={2}".format(
                selected.Symbol,
                selected.Strike,
                selected.Expiry.date()
            )
        )

    def EvaluateExit(self, slice):
        if self.held_symbol is None:
            return

        holding = self.Portfolio[self.held_symbol]

        if not holding.Invested:
            self.held_symbol = None
            self.entry_fill_price = None
            return

        expiry_date = self.Securities[self.held_symbol].Symbol.ID.Date.date()
        today = self.Time.date()

        expiration_time_stop = (
            self.Time.time() >= time(15, 45)
            and self.IsTradingDayImmediatelyBeforeExpiry(today, expiry_date)
        )

        if expiration_time_stop:
            self.SubmitExit("Expiration-preceding-day time stop")
            return

        if self.entry_fill_price is None:
            return

        quote = self.GetCurrentOptionQuote(slice, self.held_symbol)
        if quote is None:
            return

        bid, ask = quote

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if midpoint >= 1.50 * self.entry_fill_price:
            self.SubmitExit("50% profit target")

    def SubmitExit(self, reason):
        if self.held_symbol is None:
            return

        holding = self.Portfolio[self.held_symbol]
        quantity = holding.Quantity

        if quantity == 0:
            return

        if self.exit_ticket is not None and self.IsOpen(self.exit_ticket):
            self.exit_ticket.Cancel("Replacing exit order")

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )

        self.Debug(
            "Exit submitted: {0}, quantity={1}, reason={2}".format(
                self.held_symbol,
                -quantity,
                reason
            )
        )

    def ProcessExpiration(self):
        self.no_entry_today = False

        if self.held_symbol is None:
            return

        expiry_date = self.Securities[self.held_symbol].Symbol.ID.Date.date()

        if self.Time.date() >= expiry_date:
            self.no_entry_today = True
            self.Debug(
                "Unexpected expiration processing for held contract: {0}".format(
                    self.held_symbol
                )
            )
            self.SubmitExit("Expiration liquidation")

    def HandleUnexpectedEquityPosition(self):
        holding = self.Portfolio[self.spy]

        if holding.Invested:
            self.no_entry_today = True
            self.Debug(
                "Unexpected SPY equity position detected; liquidating immediately."
            )
            self.MarketOrder(
                self.spy,
                -holding.Quantity,
                tag="Unexpected exercise or assignment liquidation"
            )

    def GetCurrentOptionQuote(self, slice, symbol):
        for chain in slice.OptionChains.Values:
            contract = chain.Contracts.get(symbol)
            if contract is not None:
                return float(contract.BidPrice), float(contract.AskPrice)

        return None

    def IsTradingDayImmediatelyBeforeExpiry(self, current_date, expiry_date):
        if current_date >= expiry_date:
            return False

        candidate = current_date + timedelta(days=1)

        while candidate < expiry_date:
            if self.Securities[self.spy].Exchange.Hours.IsDateOpen(candidate):
                return False
            candidate += timedelta(days=1)

        return candidate == expiry_date and self.Securities[
            self.spy
        ].Exchange.Hours.IsDateOpen(candidate)

    def IsOpen(self, ticket):
        return ticket.Status in [
            OrderStatus.New,
            OrderStatus.PartiallyFilled,
            OrderStatus.Submitted,
            OrderStatus.CancelPending
        ]

    def OnOrderEvent(self, order_event):
        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.entry_fill_price = float(order_event.FillPrice)
                self.held_symbol = self.entry_ticket.Symbol

                self.Debug(
                    "Call entry filled: {0}, fill price={1}".format(
                        self.held_symbol,
                        self.entry_fill_price
                    )
                )

            elif order_event.Status in [
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Rejected
            ]:
                self.entry_ticket = None

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
            and order_event.Status == OrderStatus.Filled
        ):
            self.Debug(
                "Call exit filled: {0}, fill price={1}".format(
                    order_event.Symbol,
                    order_event.FillPrice
                )
            )

            self.held_symbol = None
            self.entry_fill_price = None
            self.exit_ticket = None

        is_assignment = bool(getattr(order_event, "IsAssignment", False))
        is_exercise = order_event.OrderType == OrderType.OptionExercise

        if is_assignment or is_exercise:
            self.no_entry_today = True
            self.Debug(
                "Unexpected exercise or assignment event: {0}".format(
                    order_event.Symbol
                )
            )
            self.HandleUnexpectedEquityPosition()
