            contract = chain.Contracts.get(symbol)
            if contract is not None:
                return float(contract.BidPrice), float(contract.AskPrice)

        return None

    def IsTradingDayImmediatelyBeforeExpiry(self, current_date, expiry_date):
        if current_date >= expiry_date:
            return False

        candidate = current_date + timedelta(days=1)

        while candidate < expiry_date:
