            candidate += timedelta(days=1)

        return candidate == expiry_date and self.Securities[
            self.spy
        ].Exchange.Hours.IsDateOpen(candidate)

    def IsOpen(self, ticket):
        return ticket.Status in [
            OrderStatus.New,
            OrderStatus.PartiallyFilled,
