        self.spy = spy_security.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe.IncludeWeeklys()
            .Strikes(-200, 200)
            .Expiration(0, 365)
        )
        self.option_symbol = option.Symbol

        self.close_window = deque(maxlen=20)
        self.previous_fast = None
        self.previous_slow = None

        self.current_bucket = None
        self.bucket_bars = {}
        self.last_spy_price = None

        self.held_symbol = None
        self.entry_ticket = None
        self.exit_ticket = None
        self.filled_entry_price = None
        self.blocked_entry_date = None

    def OnData(self, slice: Slice):
        self.HandleUnexpectedEquityPosition()

        current_date = self.Time.date()

        if self.held_symbol is not None:
            expiry_date = self.held_symbol.ID.Date.date()

            if current_date == expiry_date:
                self.blocked_entry_date = current_date
                self.SubmitExit("expiration-day liquidation")
            else:
                previous_day = expiry_date - timedelta(days=1)
                if (
                    current_date == previous_day
                    and self.Time.time() >= time(15, 45)
                ):
                    self.SubmitExit("expiration time stop")
                else:
                    self.CheckProfitTarget(slice)

        spy_bar = None
        if slice.Bars.ContainsKey(self.spy):
            spy_bar = slice.Bars[self.spy]
            self.last_spy_price = float(spy_bar.Close)
            self.ProcessMinuteBar(spy_bar, slice)

    def ProcessMinuteBar(self, bar: TradeBar, slice: Slice):
        bar_time = bar.Time
        if bar_time.date() != self.Time.date():
            return

        minute_of_day = bar_time.hour * 60 + bar_time.minute
        if minute_of_day < 9 * 60 + 30 or minute_of_day >= 16 * 60:
            return

        minutes_from_open = minute_of_day - (9 * 60 + 30)
        bucket_index = minutes_from_open // 5
        bucket_start = datetime(
            bar_time.year,
            bar_time.month,
            bar_time.day,
            9,
            30,
            tzinfo=bar_time.tzinfo
        ) + timedelta(minutes=bucket_index * 5)

        if self.current_bucket is None:
            self.current_bucket = bucket_start

        if bucket_start != self.current_bucket:
            self.CompleteFiveMinuteBar(self.current_bucket, slice)
            self.bucket_bars = {}
            self.current_bucket = bucket_start

        self.bucket_bars[bar_time] = bar

    def CompleteFiveMinuteBar(self, bucket_start: datetime, slice: Slice):
        expected_times = [
            bucket_start + timedelta(minutes=i) for i in range(5)
        ]

        if any(t not in self.bucket_bars for t in expected_times):
            self.Debug(
                "Skipped incomplete SPY five-minute interval ending "
                f"{(bucket_start + timedelta(minutes=5)).strftime('%H:%M')}"
            )
            return

        bars = [self.bucket_bars[t] for t in expected_times]
        close = float(bars[-1].Close)
        end_time = bucket_start + timedelta(minutes=5)

        self.close_window.append(close)

        if len(self.close_window) < 20:
            self.previous_fast = None
            self.previous_slow = None
            return

        fast = sum(list(self.close_window)[-5:]) / 5.0
        slow = sum(self.close_window) / 20.0

        bullish_crossover = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        end_clock = end_time.time()
        eligible_time = time(9, 45) <= end_clock <= time(14, 30)

        if (
            bullish_crossover
            and eligible_time
            and self.held_symbol is None
            and not self.IsEntryOrderOpen()
            and self.blocked_entry_date != self.Time.date()
        ):
            self.TryEnter(slice, close)

    def TryEnter(self, slice: Slice, spy_price: float):
        if not slice.OptionChains.ContainsKey(self.option_symbol):
            self.Debug("Skipped entry: no current SPY option chain")
            return

        contracts = []
        minimum_expiry = self.Time.date() + timedelta(days=7)

        chain = slice.OptionChains[self.option_symbol]
        for contract in chain:
            if contract.Right != OptionRight.Call:
                continue

