            candidates,
            key=lambda contract: (
                float(contract.Strike),
                str(contract.Symbol)
            )
        )

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="SPY bullish crossover call entry"
        )
        self.Debug(f"Entry submitted: {selected.Symbol}")

    def CheckProfitTarget(self, slice: Slice):
        if self.held_symbol is None or self.filled_entry_price is None:
            return

        if not slice.QuoteBars.ContainsKey(self.held_symbol):
            return

        quote = slice.QuoteBars[self.held_symbol]
        if quote.Bid is None or quote.Ask is None:
            return

        bid = float(quote.Bid.Close)
        ask = float(quote.Ask.Close)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.filled_entry_price:
            self.SubmitExit("50% profit target")

    def SubmitExit(self, reason: str):
        if self.held_symbol is None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        if self.IsExitOrderOpen():
            if self.exit_ticket is not None:
                self.exit_ticket.Cancel("replaced by liquidation")
            self.exit_ticket = None

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )
        self.Debug(f"Exit submitted: {reason}")

    def IsEntryOrderOpen(self):
        if self.entry_ticket is None:
            return False

        return self.entry_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending
        )

    def IsExitOrderOpen(self):
        if self.exit_ticket is None:
            return False

        return self.exit_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending
        )

    def HandleUnexpectedEquityPosition(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity != 0:
            self.Debug(
                f"Unexpected SPY equity position detected ({quantity}); "
                "liquidating immediately"
            )
            self.MarketOrder(
                self.spy,
                -quantity,
                tag="unexpected option exercise or assignment"
            )
            self.blocked_entry_date = self.Time.date()

    def OnOrderEvent(self, order_event: OrderEvent):
        symbol = order_event.Symbol

        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.held_symbol = symbol
                self.filled_entry_price = float(order_event.FillPrice)
                self.entry_ticket = None
                self.Debug(
                    f"Entry filled: {symbol}, price {self.filled_entry_price}"
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Ioc,
            ):
                self.Debug(f"Entry skipped: order {order_event.Status}")
                self.entry_ticket = None

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.Debug(f"Exit filled: {symbol}, price {order_event.FillPrice}")
                self.exit_ticket = None
                if self.Portfolio[symbol].Quantity == 0:
                    self.held_symbol = None
                    self.filled_entry_price = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Ioc,
            ):
                self.exit_ticket = None

        if symbol.SecurityType == SecurityType.Equity and symbol == self.spy:
            if self.Portfolio[self.spy].Quantity != 0:
                self.Debug(
                    "Unexpected exercise or assignment handling: "
                    "liquidating SPY equity"
                )
                self.MarketOrder(
                    self.spy,
                    -self.Portfolio[self.spy].Quantity,
                    tag="unexpected exercise or assignment"
                )
                self.blocked_entry_date = self.Time.date()

