        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-100, 100)
                .Expiration(0, 365)
        )

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)
        self.consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self.consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, self.consolidator)

        self.pending_signal = False
        self.entry_ticket = None
        self.entry_symbol = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.blocked_entry_date = None
        self.spy_liquidation_ticket = None

    def OnFiveMinuteBar(self, sender, bar):
        local_end = bar.EndTime

        if local_end.weekday() >= 5:
            return

        if local_end.hour < 9 or (local_end.hour == 9 and local_end.minute < 35):
            return

        if local_end.hour > 14 or (local_end.hour == 14 and local_end.minute > 30):
            return

        previous_ready = self.fast.IsReady and self.slow.IsReady
        previous_fast = self.fast.Current.Value if previous_ready else None
        previous_slow = self.slow.Current.Value if previous_ready else None

        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        if not previous_ready or not (self.fast.IsReady and self.slow.IsReady):
            return

        bullish_cross = (
            previous_fast <= previous_slow and
            self.fast.Current.Value > self.slow.Current.Value
        )

        if bullish_cross:
            self.pending_signal = True

    def OnData(self, slice):
        today = self.Time.date()

        self.ProcessUnexpectedSpyPosition(today)
        self.ProcessExpiration(today)

        if self.pending_signal:
            self.pending_signal = False
            self.TryEnter(slice, today)

        self.ProcessExitConditions(slice, today)

    def TryEnter(self, slice, today):
        if self.blocked_entry_date == today:
            return

        if self.HasOptionHolding() or self.IsOrderOpen(self.entry_ticket):
            return

        if not slice.Bars.ContainsKey(self.spy):
            self.Debug("Skipped selection: current SPY bar unavailable.")
            return

        chain = slice.OptionChains.get(self.option.Symbol)
        if chain is None or len(chain) == 0:
            self.Debug("Skipped selection: option chain unavailable.")
            return

        spy_price = slice.Bars[self.spy].Close
        minimum_strike = 1.01 * spy_price
        minimum_expiry = today + timedelta(days=7)

        eligible = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() >= minimum_expiry
        ]

        if not eligible:
            self.Debug("Skipped selection: no eligible call contracts.")
            return

        nearest_expiry = min(contract.Expiry.date() for contract in eligible)
        same_expiry = [
            contract for contract in eligible
            if contract.Expiry.date() == nearest_expiry
            and contract.Strike >= minimum_strike
        ]

        if not same_expiry:
            self.Debug("Skipped selection: no call strike at least 1% OTM.")
            return

        selected = min(
            same_expiry,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self.entry_symbol = selected.Symbol
        self.entry_ticket = self.MarketOrder(
            self.entry_symbol,
            1,
            "Bullish five-minute SMA crossover entry"
        )

    def ProcessExitConditions(self, slice, today):
        if not self.HasOptionHolding():
            return

        symbol = self.held_symbol
        expiry_date = symbol.ID.Date.date()

        if today >= expiry_date:
            self.blocked_entry_date = today
            self.SubmitOptionExit("Expiration protection")
            return

        previous_trading_day = self.PreviousTradingDay(expiry_date)
        if (
            today == previous_trading_day
            and self.Time.hour == 15
            and self.Time.minute >= 45
        ):
            self.SubmitOptionExit("Expiration time stop")
            return

        if self.entry_price is None:
            return

        if not slice.QuoteBars.ContainsKey(symbol):
            return

        quote = slice.QuoteBars[symbol]
        bid = quote.Bid.Close
        ask = quote.Ask.Close

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self.SubmitOptionExit("50% profit target")

    def SubmitOptionExit(self, reason):
        if not self.HasOptionHolding():
            return

        if self.IsOrderOpen(self.exit_ticket):
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        if self.IsOrderOpen(self.entry_ticket):
            self.entry_ticket.Cancel("Exit condition reached")

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            reason
        )
        self.Debug("Exit submitted: " + reason)

    def ProcessExpiration(self, today):
        if not self.HasOptionHolding():
            return

        expiry_date = self.held_symbol.ID.Date.date()
        if today >= expiry_date:
            self.blocked_entry_date = today
            self.SubmitOptionExit("Unexpected expiration exposure")

    def ProcessUnexpectedSpyPosition(self, today):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0:
            return

        self.blocked_entry_date = today

        if not self.IsOrderOpen(self.spy_liquidation_ticket):
            self.Debug("Unexpected exercise or assignment: liquidating SPY.")
            self.spy_liquidation_ticket = self.MarketOrder(
                self.spy,
                -quantity,
                "Unexpected exercise or assignment"
            )

    def OnAssignmentOrderEvent(self, assignment_event):
        self.blocked_entry_date = self.Time.date()
        self.Debug("Unexpected assignment detected; SPY liquidation will be submitted.")

    def OnOrderEvent(self, order_event):
        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.held_symbol = self.entry_symbol
                self.entry_price = order_event.FillPrice
                self.Debug(
                    "Entry filled: " + str(self.held_symbol) +
                    " at " + str(self.entry_price)
                )
                self.entry_ticket = None
                self.entry_symbol = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.Debug("Entry order did not fill.")
                self.entry_ticket = None
                self.entry_symbol = None

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug("Option exit filled.")
                self.exit_ticket = None
                self.held_symbol = None
                self.entry_price = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.exit_ticket = None

        if (
            self.spy_liquidation_ticket is not None
            and order_event.OrderId == self.spy_liquidation_ticket.OrderId
            and order_event.Status in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            )
        ):
            self.spy_liquidation_ticket = None

    def HasOptionHolding(self):
        return (
            self.held_symbol is not None
            and self.Portfolio[self.held_symbol].Quantity != 0
        )

    def IsOrderOpen(self, ticket):
        if ticket is None:
            return False

        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending
        )

    def PreviousTradingDay(self, date):
        previous = date - timedelta(days=1)
        while previous.weekday() >= 5:
            previous -= timedelta(days=1)
        return previous

    def OnEndOfAlgorithm(self):
        if self.HasOptionHolding():
            self.Debug("Warning: option position remained at algorithm end.")

