from AlgorithmImports import *
from collections import deque
from datetime import datetime, timedelta


class SpyFiveMinuteCallCrossover(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        equity = self.AddEquity("SPY", Resolution.Minute)
        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 730)
        )
        self.option_symbol = option.Symbol

        self.minute_bucket_date = None
        self.minute_bucket_start = None
        self.minute_bucket = []

        self.closes = deque(maxlen=20)

        self.entry_ticket = None
        self.entry_symbol = None
        self.entry_price = None

        self.exit_ticket = None
        self.blocked_date = None
        self.equity_liquidation_submitted = False

    def OnData(self, slice: Slice):
        today = self.Time.date()

        if self.blocked_date != today:
            self.equity_liquidation_submitted = False

        # Handle unexpected exercise or assignment immediately.
        equity_quantity = self.Portfolio[self.spy].Quantity
        if equity_quantity != 0:
            if not self.equity_liquidation_submitted:
                self.Debug(
                    f"{self.Time}: Unexpected SPY exercise/assignment; "
                    f"liquidating {equity_quantity} shares."
                )
                self.blocked_date = today
                self.equity_liquidation_submitted = True
                self.MarketOrder(self.spy, -equity_quantity, tag="Unexpected exercise/assignment")

        # Never intentionally carry an option into expiration.
        if self.entry_symbol is not None:
            expiry = self.entry_symbol.ID.Date.date()

            if expiry <= today:
                self.Debug(
                    f"{self.Time}: Expiration processing for {self.entry_symbol}; "
                    "liquidating option position."
                )
                self.blocked_date = today
                self._cancel_exit_order()
                quantity = self.Portfolio[self.entry_symbol].Quantity
                if quantity != 0:
                    self.exit_ticket = self.MarketOrder(
                        self.entry_symbol,
                        -quantity,
                        tag="Expiration liquidation"
                    )
                elif self.entry_ticket is not None and self._ticket_is_open(self.entry_ticket):
                    self.entry_ticket.Cancel("Expiration processing")
                return

            previous_trading_day = expiry - timedelta(days=1)
            while not self.Securities[self.spy].Exchange.Hours.IsDateOpen(previous_trading_day):
                previous_trading_day -= timedelta(days=1)

            if (
                today == previous_trading_day
                and self.Time.hour == 15
                and self.Time.minute >= 45
            ):
                self.Debug(
                    f"{self.Time}: Time-stop liquidation for {self.entry_symbol}."
                )
                self.blocked_date = today
                self._cancel_exit_order()
                quantity = self.Portfolio[self.entry_symbol].Quantity
                if quantity != 0 and not self._ticket_is_open(self.exit_ticket):
                    self.exit_ticket = self.MarketOrder(
                        self.entry_symbol,
                        -quantity,
                        tag="Pre-expiration time stop"
                    )
                return

            # Profit-target evaluation on each minute Slice.
            quote = self._find_held_contract(slice)
            if quote is not None:
                bid = float(quote.BidPrice)
                ask = float(quote.AskPrice)

                if bid > 0 and ask > 0 and self.entry_price is not None:
                    midpoint = (bid + ask) / 2.0
                    if midpoint >= 1.50 * self.entry_price:
                        self.Debug(
                            f"{self.Time}: Profit target reached for "
                            f"{self.entry_symbol}; midpoint={midpoint:.4f}."
                        )
                        self._cancel_exit_order()
                        quantity = self.Portfolio[self.entry_symbol].Quantity
                        if quantity != 0:
                            self.exit_ticket = self.MarketOrder(
                                self.entry_symbol,
                                -quantity,
                                tag="50 percent profit target"
                            )

        # Do not submit another entry while an entry order is open or a holding exists.
        if self.entry_symbol is not None:
            return

        if self.entry_ticket is not None and self._ticket_is_open(self.entry_ticket):
            return

        if self.blocked_date == today:
            return

        spy_bar = slice.Bars[self.spy] if slice.Bars.ContainsKey(self.spy) else None
        if spy_bar is None:
            return

        self._process_minute_bar(spy_bar, slice)

    def _process_minute_bar(self, bar: TradeBar, slice: Slice):
        local_time = bar.Time
        bar_date = local_time.date()
        minute = local_time.hour * 60 + local_time.minute

        # Regular-session bars only, aligned to 09:30, 09:35, ...
        if minute < 570 or minute >= 960:
            return

        if self.minute_bucket_date != bar_date or self.minute_bucket_start is None:
            self.minute_bucket_date = bar_date
            self.minute_bucket_start = local_time.replace(
                second=0, microsecond=0
            )
            self.minute_bucket = []

        expected_minute = (
            self.minute_bucket_start + timedelta(minutes=len(self.minute_bucket))
        )

        if local_time != expected_minute:
            # A missing minute invalidates this five-minute bar.
            self.minute_bucket_start = local_time.replace(
                second=0, microsecond=0
            )
            self.minute_bucket = []

        self.minute_bucket.append(bar)

        if len(self.minute_bucket) != 5:
            return

        five_minute_end = self.minute_bucket_start + timedelta(minutes=5)
        close = float(self.minute_bucket[-1].Close)

        previous_fast = None
        previous_slow = None
        if len(self.closes) >= 20:
            previous_fast = sum(list(self.closes)[-5:]) / 5.0
            previous_slow = sum(self.closes) / 20.0

        self.closes.append(close)

        if len(self.closes) < 20:
            self.minute_bucket_start = five_minute_end
            self.minute_bucket = []
            return

        current_fast = sum(list(self.closes)[-5:]) / 5.0
        current_slow = sum(self.closes) / 20.0

        crossover = (
            previous_fast is not None
            and previous_slow is not None
            and previous_fast <= previous_slow
            and current_fast > current_slow
        )

        end_minutes = five_minute_end.hour * 60 + five_minute_end.minute
        eligible_time = 585 <= end_minutes <= 870  # 09:45 through 14:30

        if crossover and eligible_time:
            self._attempt_entry(slice, close)

        self.minute_bucket_start = five_minute_end
        self.minute_bucket = []

    def _attempt_entry(self, slice: Slice, spy_price: float):
        if not slice.OptionChains.ContainsKey(self.option_symbol):
            self.Debug(f"{self.Time}: Skipped selection; no option chain in Slice.")
            return

        minimum_expiry = self.Time.date() + timedelta(days=7)
        contracts = []

        chain = slice.OptionChains[self.option_symbol]
        for contract in chain:
            if contract.Right != OptionRight.Call:
                continue
            if contract.Expiry.date() < minimum_expiry:
                continue
            if contract.Strike < 1.01 * spy_price:
                continue
            contracts.append(contract)

        if not contracts:
            self.Debug(
                f"{self.Time}: Skipped selection; no eligible call contract."
            )
            return

        nearest_expiry = min(contract.Expiry.date() for contract in contracts)
        candidates = [
            contract for contract in contracts
            if contract.Expiry.date() == nearest_expiry
        ]

        selected = sorted(
            candidates,
            key=lambda contract: (float(contract.Strike), str(contract.Symbol))
        )[0]

        self.entry_symbol = selected.Symbol
        self.entry_price = None
        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )

        self.Debug(
            f"{self.Time}: Entry submitted for {selected.Symbol}; "
            f"expiry={nearest_expiry}, strike={selected.Strike:.2f}."
        )

    def _find_held_contract(self, slice: Slice):
        if self.entry_symbol is None:
            return None

        for chain in slice.OptionChains:
            for contract in chain:
                if contract.Symbol == self.entry_symbol:
                    return contract

        return None

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
