                    self.held_expiry = self.Securities[
                        self.held_option
                    ].Symbol.ID.Date.date()
                    self.Debug(
                        f"{self.Time}: entry filled; "
                        f"{self.held_option} at {self.entry_price:.4f}"
                    )
                    self.entry_ticket = None
                elif order_event.Status == OrderStatus.Canceled:
                    self.entry_ticket = None

        if self.exit_ticket is not None:
            if order_event.OrderId == self.exit_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.Debug(
                        f"{self.Time}: exit filled for "
                        f"{self.exit_ticket.Symbol}"
                    )
                    self.exit_ticket = None
                    self.held_option = None
                    self.held_expiry = None
                    self.entry_price = None
                elif order_event.Status == OrderStatus.Canceled:
                    self.exit_ticket = None

        order = self.Transactions.GetOrderById(order_event.OrderId)
        if order is not None:
            order_type = str(order.Type)
            if "Exercise" in order_type or "Assignment" in order_type:
                self.no_entry_date = self.Time.date()
                self.Debug(
                    f"{self.Time}: unexpected {order_type} order event"
                )

