from AlgorithmImports import *
from collections import deque
from datetime import timedelta, datetime, time


class SpyCallCrossoverAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        self.spy = self.AddEquity("SPY", Resolution.Minute)
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy_symbol = self.spy.Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-100, 100)
                .Expiration(timedelta(0), timedelta(days=365))
        )
        self.option_symbol = self.option.Symbol

        self.closes = deque(maxlen=20)
        self.fast_period = 5
        self.slow_period = 20

        self.bucket_date = None
        self.bucket_end_minute = None
        self.bucket_bars = {}

        self.previous_fast = None
        self.previous_slow = None

        self.entry_ticket = None
        self.entry_symbol = None
        self.held_symbol = None
        self.held_expiry = None
        self.entry_price = None
        self.exit_ticket = None
        self.blocked_date = None

    def OnData(self, slice: Slice):
        current_date = self.Time.date()

        self._handle_unexpected_equity_position(current_date)
        self._handle_expiration()

        spy_bar = None
        if self.spy_symbol in slice.Bars:
            spy_bar = slice.Bars[self.spy_symbol]
            self._process_minute_bar(spy_bar, slice)

        if self.held_symbol is not None:
            self._evaluate_exits(slice)

    def _process_minute_bar(self, bar: TradeBar, slice: Slice):
        local_time = self.Time
        minute_of_day = local_time.hour * 60 + local_time.minute

        # Regular session minute bars, using 09:30 as the first bucket boundary.
        if minute_of_day < 570 or minute_of_day > 960:
            return

        bucket_end_minute = 570 + ((minute_of_day - 570) // 5 + 1) * 5
        bucket_date = local_time.date()

        if self.bucket_date != bucket_date or self.bucket_end_minute != bucket_end_minute:
            self._discard_incomplete_bucket()

            self.bucket_date = bucket_date
            self.bucket_end_minute = bucket_end_minute
            self.bucket_bars = {}

        self.bucket_bars[minute_of_day] = bar

        expected_minutes = range(bucket_end_minute - 5, bucket_end_minute)
        if not all(minute in self.bucket_bars for minute in expected_minutes):
            return

        closes = [self.bucket_bars[minute].Close for minute in expected_minutes]
        consolidated_close = closes[-1]

        previous_fast = None
        previous_slow = None

        if len(self.closes) >= self.slow_period:
            previous_fast = sum(list(self.closes)[-self.fast_period:]) / self.fast_period
            previous_slow = sum(self.closes) / self.slow_period

        self.closes.append(consolidated_close)

        if len(self.closes) < self.slow_period:
            return

        current_fast = sum(list(self.closes)[-self.fast_period:]) / self.fast_period
        current_slow = sum(self.closes) / self.slow_period

        crossover = (
            previous_fast is not None
            and previous_slow is not None
            and previous_fast <= previous_slow
            and current_fast > current_slow
        )

        bar_end_time = datetime.combine(
            bucket_date,
            time(bucket_end_minute // 60, bucket_end_minute % 60)
        )

        if crossover and time(9, 45) <= bar_end_time.time() <= time(14, 30):
            self._try_enter(slice, consolidated_close, bucket_date)

    def _try_enter(self, slice: Slice, spy_price: float, current_date):
        if current_date == self.blocked_date:
            return

        if self.held_symbol is not None or self._entry_order_open():
            return

        chains = []
        try:
            chain = slice.OptionChains.get(self.option_symbol)
            if chain is not None:
                chains.append(chain)
        except Exception:
            pass

        if not chains:
            try:
                chains = list(slice.OptionChains)
            except Exception:
                chains = []

        if not chains:
            self.Debug("Skipped selection: no current SPY option chain.")
            return

        minimum_expiry = current_date + timedelta(days=7)
        candidates = []

        for chain in chains:
            try:
                contracts = chain.Contracts
                values = contracts.Values
            except Exception:
                continue

            for contract in values:
                if contract.Right != OptionRight.Call:
                    continue

                expiry_date = contract.Expiry.date()
                if expiry_date < minimum_expiry:
                    continue

                if contract.Strike < 1.01 * spy_price:
                    continue

                candidates.append(contract)

        if not candidates:
            self.Debug("Skipped selection: no qualifying call contract.")
            return

        nearest_expiry = min(contract.Expiry.date() for contract in candidates)
        candidates = [
            contract for contract in candidates
            if contract.Expiry.date() == nearest_expiry
        ]

        selected = min(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self.entry_symbol = selected.Symbol
        self.entry_ticket = self.MarketOrder(self.entry_symbol, 1)
        self.Debug(
            f"Entry submitted: {self.entry_symbol}; "
            f"expiry={nearest_expiry}; strike={selected.Strike}"
        )

    def _evaluate_exits(self, slice: Slice):
        if self.entry_price is None or self.held_symbol is None:
            return

        if self._exit_order_open():
            return

        contract = self._get_current_contract(slice, self.held_symbol)
        bid = None
        ask = None

        if contract is not None:
            bid = contract.BidPrice
            ask = contract.AskPrice

        if bid is not None and ask is not None and bid > 0 and ask > 0:
            midpoint = (bid + ask) / 2.0
            if midpoint >= 1.50 * self.entry_price:
                self._submit_exit("profit target")
                return

        if self.held_expiry is not None:
            preceding_day = self._preceding_trading_day(self.held_expiry.date())
            if (
                self.Time.date() == preceding_day
                and self.Time.time() >= time(15, 45)
            ):
                self._submit_exit("expiration time stop")

