        minute_of_day = local_time.hour * 60 + local_time.minute

        # Regular session minute bars, using 09:30 as the first bucket boundary.
        if minute_of_day < 570 or minute_of_day > 960:
            return

        bucket_end_minute = 570 + ((minute_of_day - 570) // 5 + 1) * 5
        bucket_date = local_time.date()

