from datetime import datetime, timedelta

from QuantConnect import TimeZones, DataNormalizationMode, OrderStatus, SecurityType
from QuantConnect.Algorithm import QCAlgorithm
from QuantConnect.Data.Market import TradeBar
from QuantConnect.Indicators import SimpleMovingAverage
from QuantConnect.Securities import Resolution
from QuantConnect.Securities.Option import OptionRight


class SpyCallCrossoverAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetTimeZone(TimeZones.NewYork)
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)

        equity = self.AddEquity("SPY", Resolution.Minute)
        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe
            .IncludeWeeklys()
            .Strikes(-200, 200)
            .Expiration(0, 365)
        )

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self._bucket_date = None
        self._bucket_end = None
        self._bucket_count = 0
        self._bucket_open = None
        self._bucket_high = None
        self._bucket_low = None
        self._bucket_close = None
        self._bucket_volume = 0

        self._entry_ticket = None
        self._held_symbol = None
        self._entry_price = None
        self._exit_ticket = None
        self._blocked_dates = set()

    def OnData(self, slice):
        current_date = self.Time.date()

        if self.Portfolio[self.spy].Invested:
            self._blocked_dates.add(current_date)
            self.Debug("Unexpected SPY equity position detected; liquidating immediately.")
            self.MarketOrder(self.spy, -self.Portfolio[self.spy].Quantity)

        if self._held_symbol is not None:
            self._process_expiration_and_time_stop(current_date)

            if self._held_symbol is not None and self._exit_ticket is None:
                self._process_profit_target(slice)

        if self.spy in slice.Bars:
            self._process_minute_bar(slice.Bars[self.spy], slice)

    def _process_minute_bar(self, minute_bar, slice):
        local_time = minute_bar.EndTime
        if local_time.tzinfo is not None:
            local_time = local_time.replace(tzinfo=None)

        bar_date = local_time.date()
        bar_start = local_time - timedelta(minutes=1)
        start_time = bar_start.time()
        if start_time < datetime.strptime("09:30", "%H:%M").time():
            return
        if start_time >= datetime.strptime("16:00", "%H:%M").time():
            return

        end_minute = local_time.replace(second=0, microsecond=0)
        bucket_minute = ((end_minute.minute + 4) // 5) * 5
        bucket_end = end_minute.replace(minute=0) + timedelta(minutes=bucket_minute)

        if (
            self._bucket_end is not None
            and (bar_date != self._bucket_date or bucket_end != self._bucket_end)
        ):
            self._finalize_bucket(slice)

        if self._bucket_end != bucket_end or self._bucket_date != bar_date:
            self._bucket_date = bar_date
            self._bucket_end = bucket_end
            self._bucket_count = 0
            self._bucket_open = None
            self._bucket_high = None
            self._bucket_low = None
            self._bucket_close = None
            self._bucket_volume = 0

        self._bucket_count += 1
        if self._bucket_open is None:
            self._bucket_open = minute_bar.Open
            self._bucket_high = minute_bar.High
            self._bucket_low = minute_bar.Low
        else:
            self._bucket_high = max(self._bucket_high, minute_bar.High)
            self._bucket_low = min(self._bucket_low, minute_bar.Low)

        self._bucket_close = minute_bar.Close
        self._bucket_volume += minute_bar.Volume

    def _finalize_bucket(self, slice):
        if self._bucket_end is None:
            return

        if self._bucket_count != 5:
            self._reset_bucket()
            return

        end_time = self._bucket_end
        if end_time.time() < datetime.strptime("09:45", "%H:%M").time():
            self._update_averages(end_time)
        elif end_time.time() <= datetime.strptime("14:30", "%H:%M").time():
            bullish = self._update_averages(end_time)
            if bullish:
                self._try_entry(slice, self._bucket_close)

        self._reset_bucket()

    def _update_averages(self, end_time):
        previous_ready = self.fast.IsReady and self.slow.IsReady
        previous_fast = self.fast.Current.Value if previous_ready else None
        previous_slow = self.slow.Current.Value if previous_ready else None

        self.fast.Update(end_time, self._bucket_close)
        self.slow.Update(end_time, self._bucket_close)

        if not previous_ready or not self.fast.IsReady or not self.slow.IsReady:
            return False

        return (
            previous_fast <= previous_slow
            and self.fast.Current.Value > self.slow.Current.Value
        )

    def _reset_bucket(self):
        self._bucket_date = None
        self._bucket_end = None
        self._bucket_count = 0
        self._bucket_open = None
        self._bucket_high = None
        self._bucket_low = None
        self._bucket_close = None
        self._bucket_volume = 0

    def _try_entry(self, slice, spy_price):
        current_date = self.Time.date()

        if current_date in self._blocked_dates:
            return
        if self._held_symbol is not None:
            return
        if self._entry_ticket is not None:
            return

        selected = self._select_option(slice, spy_price, current_date)
        if selected is None:
            self.Debug("Skipped option selection: no qualifying call contract.")
            return

        self._entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug("Submitted entry for " + str(selected.Symbol))

    def _select_option(self, slice, spy_price, current_date):
        minimum_expiry = current_date + timedelta(days=7)
        candidates = []

        for chain in slice.OptionChains.Values:
            for contract in chain:
                if contract.Right != OptionRight.Call:
                    continue

                expiry_date = contract.Expiry.date()
                if expiry_date < minimum_expiry:
                    continue

                if contract.Strike < 1.01 * spy_price:
                    continue

                candidates.append(contract)

        if not candidates:
            return None

        nearest_expiry = min(contract.Expiry.date() for contract in candidates)
        candidates = [
            contract
            for contract in candidates
            if contract.Expiry.date() == nearest_expiry
        ]

        return min(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

    def _process_profit_target(self, slice):
        if self._held_symbol not in slice.Bars:
            return

        chain_contract = None
        for chain in slice.OptionChains.Values:
            for contract in chain:
                if contract.Symbol == self._held_symbol:
                    chain_contract = contract
                    break
            if chain_contract is not None:
                break

        if chain_contract is None:
            return

        bid = chain_contract.BidPrice
        ask = chain_contract.AskPrice
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.5 * self._entry_price:
            self._submit_exit("profit target")

    def _process_expiration_and_time_stop(self, current_date):
        if self._held_symbol is None:
            return

        expiry_date = self._held_symbol.ID.Date.date()

        if current_date >= expiry_date:
            self._blocked_dates.add(current_date)
            self._submit_exit("expiration protection")
            return

        previous_trading_day = self._previous_trading_day(expiry_date)
        if (
            current_date == previous_trading_day
            and self.Time.time() >= datetime.strptime("15:45", "%H:%M").time()
        ):
            self._submit_exit("expiration time stop")

    def _previous_trading_day(self, expiry_date):
        candidate = expiry_date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate

    def _submit_exit(self, reason):
        if self._held_symbol is None or self._exit_ticket is not None:
            return

        existing = self.Transactions.GetOpenOrders(self._held_symbol)
        for order in existing:
            self.Transactions.CancelOrder(order.Id)

        quantity = self.Portfolio[self._held_symbol].Quantity
        if quantity == 0:
            return

        self._exit_ticket = self.MarketOrder(self._held_symbol, -quantity)
        self.Debug("Submitted " + reason + " exit for " + str(self._held_symbol))

    def OnOrderEvent(self, order_event):
        if (
            self._entry_ticket is not None
            and order_event.OrderId == self._entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self._held_symbol = order_event.Symbol
                self._entry_price = order_event.FillPrice
                self._entry_ticket = None
                self.Debug(
                    "Entry filled: "
                    + str(self._held_symbol)
                    + " at "
                    + str(self._entry_price)
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.MarginInterest,
            ):
                self._entry_ticket = None
            return

        if (
            self._exit_ticket is not None
            and order_event.OrderId == self._exit_ticket.OrderId
            and order_event.Status == OrderStatus.Filled
        ):
            self.Debug("Exit filled for " + str(order_event.Symbol))
            self._exit_ticket = None
            if not self.Portfolio[order_event.Symbol].Invested:
                self._held_symbol = None
                self._entry_price = None

    def OnAssignmentOrderEvent(self, assignment_event):
        self.Debug("Unexpected option exercise or assignment handled immediately.")
        self._blocked_dates.add(self.Time.date())

        if self.Portfolio[self.spy].Invested:
            self.MarketOrder(self.spy, -self.Portfolio[self.spy].Quantity)

