from AlgorithmImports import *
from collections import deque
from datetime import timedelta


class SpyCallCrossoverAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        equity = self.AddEquity("SPY", Resolution.Minute)
        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 365)
        )
        self.option_symbol = self.option.Symbol

        self.closes = deque(maxlen=20)
        self.bucket_end = None
        self.bucket_bars = {}

        self.entry_order_id = None
        self.held_symbol = None
        self.entry_price = None
        self.exit_order_id = None

        self.no_entry_today = False
        self.current_date = None
        self.time_stop_date = None

    def OnData(self, slice: Slice):
        today = self.Time.date()

        if self.current_date != today:
            self.current_date = today
            self.no_entry_today = False

        # Immediately remove any unexpected SPY equity position.
        spy_quantity = self.Portfolio[self.spy].Quantity
        if spy_quantity != 0:
            self.Debug(
                f"Unexpected SPY equity position detected ({spy_quantity}); liquidating."
            )
            self.MarketOrder(
                self.spy,
                -spy_quantity,
                tag="Unexpected exercise or assignment"
            )
            self.no_entry_today = True

        # Never intentionally hold an option into expiration.
        if self.held_symbol is not None:
            expiry_date = self.Securities[self.held_symbol].Symbol.ID.Date.date()

            if today >= expiry_date:
                self.no_entry_today = True
                self._submit_exit("Expiration liquidation")
            else:
                self._evaluate_exit(slice, today, expiry_date)

        spy_bar = slice.Bars.get(self.spy)
        if spy_bar is not None:
            self._process_minute_bar(spy_bar, slice)

    def _process_minute_bar(self, minute_bar: TradeBar, slice: Slice):
        end_time = minute_bar.EndTime
        local_time = end_time

        if local_time.date() != self.Time.date():
            local_time = self.Time

        if not (local_time.hour == 9 and local_time.minute >= 31) and not (
            10 <= local_time.hour <= 15
        ) and not (local_time.hour == 16 and local_time.minute == 0):
            return

        if local_time.hour == 9 and local_time.minute < 31:
            return

        minute = local_time.minute
        bucket_minute = minute + (5 - minute % 5) % 5
        if bucket_minute == minute and minute % 5 != 0:
            bucket_minute += 5

        bucket_end = local_time.replace(
            minute=bucket_minute,
            second=0,
            microsecond=0
        )

        if self.bucket_end is not None and bucket_end != self.bucket_end:
            self._finish_bucket(slice)

        if self.bucket_end != bucket_end:
            self.bucket_end = bucket_end
            self.bucket_bars = {}

        self.bucket_bars[local_time] = minute_bar

        if local_time == bucket_end:
            self._finish_bucket(slice)

    def _finish_bucket(self, slice: Slice):
        if self.bucket_end is None:
            return

        expected_times = [
            self.bucket_end - timedelta(minutes=i)
            for i in range(4, -1, -1)
        ]

        if all(timestamp in self.bucket_bars for timestamp in expected_times):
            close = self.bucket_bars[expected_times[-1]].Close
            self._process_consolidated_close(close, self.bucket_end, slice)

        self.bucket_end = None
        self.bucket_bars = {}

    def _process_consolidated_close(self, close: float, bar_end, slice: Slice):
        if len(self.closes) >= 20:
            previous_fast = sum(list(self.closes)[-5:]) / 5.0
            previous_slow = sum(self.closes) / 20.0
        else:
            previous_fast = None
            previous_slow = None

        self.closes.append(float(close))

        if len(self.closes) < 20:
            return

        current_fast = sum(list(self.closes)[-5:]) / 5.0
        current_slow = sum(self.closes) / 20.0

        bullish_cross = (
            previous_fast is not None
            and previous_slow is not None
            and previous_fast <= previous_slow
            and current_fast > current_slow
        )

        if not bullish_cross:
            return

        if not (bar_end.hour > 9 or (bar_end.hour == 9 and bar_end.minute >= 45)):
            return

        if bar_end.hour > 14 or (bar_end.hour == 14 and bar_end.minute > 30):
            return

        if (
            self.held_symbol is not None
            or self.entry_order_id is not None
            or self.no_entry_today
        ):
            return

        spy_bar = slice.Bars.get(self.spy)
        spy_price = float(spy_bar.Close) if spy_bar is not None else float(self.Securities[self.spy].Price)

        self._select_and_enter(slice, spy_price)

    def _select_and_enter(self, slice: Slice, spy_price: float):
        chain = slice.OptionChains.get(self.option_symbol)

        if chain is None:
            self.Debug("Skipped selection: no current SPY option chain.")
            return

        algorithm_date = self.Time.date()
        minimum_expiry = algorithm_date + timedelta(days=7)
        minimum_strike = 1.01 * spy_price

        candidates = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() >= minimum_expiry
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped selection: no qualifying SPY call contract.")
            return

        nearest_expiry = min(contract.Expiry.date() for contract in candidates)
        candidates = [
            contract for contract in candidates
            if contract.Expiry.date() == nearest_expiry
        ]

        selected = min(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self.entry_order_id = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover"
        ).OrderId

        self.Debug(
            f"Entry submitted: {selected.Symbol}, "
            f"expiry={nearest_expiry}, strike={selected.Strike}"
        )

    def _evaluate_exit(self, slice: Slice, today, expiry_date):
        if self.exit_order_id is not None:
            return

        if self.time_stop_date is None:
            self.time_stop_date = self._previous_trading_day(expiry_date)

        if today == self.time_stop_date and (
            self.Time.hour > 15
            or (self.Time.hour == 15 and self.Time.minute >= 45)
        ):
            self._submit_exit("Expiration-eve time stop")
            return

        chain = slice.OptionChains.get(self.option_symbol)
        if chain is None or self.held_symbol is None:
            return

        held_contract = next(
            (contract for contract in chain if contract.Symbol == self.held_symbol),
            None
        )

        if held_contract is None:
            return

        bid = float(held_contract.BidPrice)
        ask = float(held_contract.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if self.entry_price is not None and midpoint >= 1.50 * self.entry_price:
            self._submit_exit("50 percent profit target")

    def _submit_exit(self, reason: str):
        if self.held_symbol is None:
            return

        if self.exit_order_id is not None:
            self.Transactions.CancelOrder(self.exit_order_id)

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity <= 0:
            return

        self.exit_order_id = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        ).OrderId

        self.Debug(f"Exit submitted: {self.held_symbol}; reason={reason}")

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_order_id == order_event.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.held_symbol = order_event.Symbol
                self.entry_price = float(order_event.FillPrice)
                self.entry_order_id = None
                self.time_stop_date = None
                self.Debug(
                    f"Entry filled: {self.held_symbol}, "
                    f"price={self.entry_price}"
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.None_
            ):
                self.entry_order_id = None

        if self.exit_order_id == order_event.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(f"Exit filled: {order_event.Symbol}")
                self.exit_order_id = None
                self.held_symbol = None
                self.entry_price = None
                self.time_stop_date = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.exit_order_id = None

    def OnAssignmentOrder(self, assignment_event):
        self.Debug("Unexpected exercise or assignment received.")
        self.no_entry_today = True

        quantity = self.Portfolio[self.spy].Quantity
        if quantity != 0:
            self.MarketOrder(
                self.spy,
                -quantity,
                tag="Unexpected exercise or assignment"
            )

    def _previous_trading_day(self, date):
        exchange_hours = self.Securities[self.spy].Exchange.Hours
        candidate = date - timedelta(days=1)

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate.date() if hasattr(candidate, "date") else candidate

