from AlgorithmImports import *
from collections import deque
from datetime import datetime, timedelta, time


class SpyFiveMinuteCallCrossover(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            data_normalization_mode=DataNormalizationMode.Raw,
            extended_market_hours=False
        ).Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 730)
        )

        self.fast_period = 5
        self.slow_period = 20
        self.closes = deque(maxlen=self.slow_period)
        self.previous_fast = None
        self.previous_slow = None

        self.bucket_date = None
        self.bucket_end_minute = None
        self.bucket_minutes = set()
        self.bucket_open = None
        self.bucket_high = None
        self.bucket_low = None
        self.bucket_close = None

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.no_entry_date = None
        self.equity_liquidation_ticket = None

    def OnData(self, slice: Slice):
        self._handle_unexpected_spy_position()
        self._process_expiration()

        current_chain = self._get_current_option_chain(slice)

        spy_bar = None
        if slice.Bars.ContainsKey(self.spy):
            spy_bar = slice.Bars[self.spy]
            self._process_minute_bar(spy_bar, current_chain)

        self._evaluate_held_option_exit(slice)

    def _process_minute_bar(self, minute_bar: TradeBar, current_chain):
        end_time = self.Time
        if end_time.time() < time(9, 30) or end_time.time() > time(16, 0):
            return

        total_minutes = end_time.hour * 60 + end_time.minute
        bucket_end = ((total_minutes - 1) // 5 + 1) * 5
        bucket_date = end_time.date()

        if (
            self.bucket_date != bucket_date
            or self.bucket_end_minute != bucket_end
        ):
            self.bucket_date = bucket_date
            self.bucket_end_minute = bucket_end
            self.bucket_minutes = set()
            self.bucket_open = None
            self.bucket_high = None
            self.bucket_low = None
            self.bucket_close = None

        minute_key = total_minutes
        if minute_key in self.bucket_minutes:
            return

        self.bucket_minutes.add(minute_key)

        if self.bucket_open is None:
            self.bucket_open = minute_bar.Open
            self.bucket_high = minute_bar.High
            self.bucket_low = minute_bar.Low
        else:
            self.bucket_high = max(self.bucket_high, minute_bar.High)
            self.bucket_low = min(self.bucket_low, minute_bar.Low)

        self.bucket_close = minute_bar.Close

        # A valid five-minute bar requires all five minute observations.
        if len(self.bucket_minutes) != 5:
            return

        bar_end = datetime(
            bucket_date.year,
            bucket_date.month,
            bucket_date.day,
            bucket_end // 60,
            bucket_end % 60
        )

        self._process_completed_five_minute_bar(
            self.bucket_close,
            bar_end,
            current_chain
        )

    def _process_completed_five_minute_bar(
        self,
        close: float,
        bar_end: datetime,
        current_chain
    ):
        if len(self.closes) >= self.slow_period:
            self.previous_fast = sum(
                list(self.closes)[-self.fast_period:]
            ) / self.fast_period
            self.previous_slow = sum(self.closes) / self.slow_period

        self.closes.append(close)

        if len(self.closes) < self.slow_period:
            return

        current_fast = sum(list(self.closes)[-self.fast_period:]) / self.fast_period
        current_slow = sum(self.closes) / self.slow_period

        bullish_crossover = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and current_fast > current_slow
        )

        eligible_time = time(9, 45) <= bar_end.time() <= time(14, 30)

        if (
            bullish_crossover
            and eligible_time
            and self.no_entry_date != bar_end.date()
            and self.held_symbol is None
            and not self._is_order_open(self.entry_ticket)
        ):
            self._enter_call(current_chain, close)

    def _enter_call(self, chains, spy_price: float):
        if chains is None:
            self.Debug("Skipped selection: no option chain in current Slice.")
            return

        minimum_expiration = self.Time.date() + timedelta(days=7)
        candidates = []

        for chain in chains:
            for contract in chain:
                expiration_date = contract.Expiration.date()
                if expiration_date < minimum_expiration:
                    continue
                if contract.Right != OptionRight.Call:
                    continue
                if contract.Strike < 1.01 * spy_price:
                    continue

                candidates.append(contract)

        if not candidates:
            self.Debug("Skipped selection: no qualifying call contract.")
            return

        nearest_expiration = min(
            contract.Expiration.date() for contract in candidates
        )

        candidates = [
            contract for contract in candidates
            if contract.Expiration.date() == nearest_expiration
        ]

        selected = min(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            "Entry submitted: {} expiration={} strike={}".format(
                selected.Symbol,
                selected.Expiration.date(),
                selected.Strike
            )
        )

    def _evaluate_held_option_exit(self, slice: Slice):
        if self.held_symbol is None or self.entry_price is None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity <= 0:
            return

        expiration_date = self.Securities[self.held_symbol].Symbol.ID.Date.date()
        current_date = self.Time.date()

        if self._is_last_trading_day_before_expiration(
            current_date,
            expiration_date
        ) and self.Time.time() >= time(15, 45):
            self._submit_option_exit("time stop")
            return

        if self._is_order_open(self.exit_ticket):
            return

        contract = self._find_held_contract(slice)
        if contract is None:
            return

        bid = contract.BidPrice
        ask = contract.AskPrice

        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            if self._is_order_open(self.exit_ticket):
                self.exit_ticket.Cancel("Profit target superseded prior exit")
            self._submit_option_exit("profit target")

    def _submit_option_exit(self, reason: str):
        if self.held_symbol is None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity <= 0:
            return

        if self._is_order_open(self.exit_ticket):
            return

        self.exit_ticket = self.MarketOrder(self.held_symbol, -quantity)
        self.Debug(
            "Exit submitted: {} reason={}".format(self.held_symbol, reason)
        )

    def _process_expiration(self):
        if self.held_symbol is None:
            return

        expiration_date = self.Securities[self.held_symbol].Symbol.ID.Date.date()
        if expiration_date <= self.Time.date():
            self.no_entry_date = self.Time.date()
            self._submit_option_exit("expiration processing")

    def _handle_unexpected_spy_position(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0:
            return

        if not self._is_order_open(self.equity_liquidation_ticket):
            self.Debug(
                "Unexpected exercise or assignment handling: liquidating SPY "
                "equity position of {} shares.".format(quantity)
            )
            self.equity_liquidation_ticket = self.MarketOrder(
                self.spy,
                -quantity
            )

    def _find_held_contract(self, slice: Slice):
        for chain in slice.OptionChains:
            for contract in chain:
                if contract.Symbol == self.held_symbol:
                    return contract
        return None

    def _get_current_option_chain(self, slice: Slice):
        chains = []
        for chain in slice.OptionChains:
            if chain.Underlying.Symbol == self.spy:
                chains.append(chain)
        return chains if chains else None

    def _is_last_trading_day_before_expiration(
        self,
        current_date,
        expiration_date
    ):
        if current_date >= expiration_date:
            return False

        date = expiration_date - timedelta(days=1)
        while not self.Securities[self.spy].Exchange.Hours.IsDateOpen(
            datetime(date.year, date.month, date.day)
        ):
            date -= timedelta(days=1)

        return current_date == date

    def _is_order_open(self, ticket):
        if ticket is None:
            return False

        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending,
            OrderStatus.UpdateSubmitted
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None:
            if order_event.OrderId == self.entry_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.held_symbol = order_event.Symbol
                    self.entry_price = order_event.FillPrice
                    self.entry_ticket = None
                    self.Debug(
                        "Entry filled: {} price={}".format(
                            self.held_symbol,
                            self.entry_price
                        )
                    )
                elif order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid
                ):
                    self.entry_ticket = None

        if self.exit_ticket is not None:
            if order_event.OrderId == self.exit_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.Debug(
                        "Exit filled: {} price={}".format(
                            order_event.Symbol,
                            order_event.FillPrice
                        )
                    )
                    self.exit_ticket = None
                    if self.Portfolio[order_event.Symbol].Quantity == 0:
                        self.held_symbol = None
                        self.entry_price = None
                elif order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid
                ):
                    self.exit_ticket = None

        if self.equity_liquidation_ticket is not None:
            if order_event.OrderId == self.equity_liquidation_ticket.OrderId:
                if order_event.Status in (
                    OrderStatus.Filled,
                    OrderStatus.Canceled,
                    OrderStatus.Invalid
                ):
                    self.equity_liquidation_ticket = None

