                self._blocked_entry_date = current_date
                self.MarketOrder(
                    self.spy,
                    -self.Portfolio[self.spy].Quantity,
                    tag="unexpected exercise or assignment"
                )

        if self._has_option_position():
            self._evaluate_option_exit(slice)

        spy_bar = slice.Bars.get(self.spy)
        if spy_bar is None:
            return

        completed_bar = self._consolidate_minute_bar(spy_bar)
        if completed_bar is None:
            return

        self.fast.Update(completed_bar.EndTime, completed_bar.Close)
        self.slow.Update(completed_bar.EndTime, completed_bar.Close)

        if not self.fast.IsReady or not self.slow.IsReady:
            return

        fast_value = self.fast.Current.Value
        slow_value = self.slow.Current.Value

        bullish_cross = (
            self._previous_fast is not None
            and self._previous_slow is not None
            and self._previous_fast <= self._previous_slow
            and fast_value > slow_value
        )

        self._previous_fast = fast_value
        self._previous_slow = slow_value

        bar_time = completed_bar.EndTime
        eligible_time = (
            datetime(2000, 1, 1, 9, 45).time()
            <= bar_time.time()
            <= datetime(2000, 1, 1, 14, 30).time()
        )

        if (
            bullish_cross
            and eligible_time
            and self._blocked_entry_date != current_date
            and not self._has_option_position()
            and not self._entry_order_is_open()
            and self._exit_order_id is None
        ):
            self._enter_call(slice, spy_bar.Close, current_date)

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.Status in [
            OrderStatus.Canceled,
            OrderStatus.Invalid,
            OrderStatus.Rejected
        ]:
            if order_event.OrderId == self._entry_order_id:
                self._entry_order_id = None
            if order_event.OrderId == self._exit_order_id:
                self._exit_order_id = None
            return

        if order_event.OrderId == self._entry_order_id:
            if order_event.FillQuantity > 0:
                self._held_contract = order_event.Symbol
                self._entry_price = order_event.FillPrice
                self.Debug(
                    f"{self.Time}: Entered {order_event.Symbol} call, "
                    f"fill price {order_event.FillPrice:.4f}"
                )

            if order_event.Status == OrderStatus.Filled:
                self._entry_order_id = None

        elif order_event.OrderId == self._exit_order_id:
            if order_event.FillQuantity != 0:
                self.Debug(
                    f"{self.Time}: Exited {order_event.Symbol}, "
                    f"fill price {order_event.FillPrice:.4f}"
                )

            if order_event.Status == OrderStatus.Filled:
                self._exit_order_id = None
                self._held_contract = None
                self._entry_price = None

        if order_event.OrderType == OrderType.OptionExercise:
            self._blocked_entry_date = self.Time.date()
