                self.MarketOrder(
                    self.spy,
                    -self.Portfolio[self.spy].Quantity,
                    tag="unexpected exercise or assignment"
                )

    def _consolidate_minute_bar(self, bar: TradeBar):
        local_end = bar.EndTime.astimezone(self.TimeZone)
        if local_end.weekday() >= 5:
            return None

        end_time = local_end.time()
        if end_time < datetime(2000, 1, 1, 9, 31).time():
            return None
        if end_time > datetime(2000, 1, 1, 16, 0).time():
            return None

        minute = local_end.minute
        bucket_number = ((minute - 30 + 4) // 5) * 5 + 30
        if bucket_number > 60:
            bucket_end = local_end.replace(
                hour=local_end.hour + 1,
                minute=bucket_number - 60,
                second=0,
                microsecond=0
            )
        else:
            bucket_end = local_end.replace(
                minute=bucket_number,
                second=0,
                microsecond=0
            )

        key = bucket_end
        bucket = self._minute_bars.setdefault(key, {})
        bucket[local_end] = bar

        expected_times = [
            bucket_end - timedelta(minutes=i)
            for i in range(4, -1, -1)
        ]

        if local_end != bucket_end:
            return None

        if any(expected not in bucket for expected in expected_times):
            self.Debug(
                f"{bucket_end}: Incomplete five-minute SPY bar skipped."
            )
            self._minute_bars.pop(key, None)
            return None

        bars = [bucket[t] for t in expected_times]
        self._minute_bars.pop(key, None)

        consolidated = TradeBar(
            bars[0].Time,
            self.spy,
            bars[0].Open,
            max(x.High for x in bars),
            min(x.Low for x in bars),
            bars[-1].Close,
            sum(x.Volume for x in bars),
            timedelta(minutes=5)
        )
        return consolidated

    def _enter_call(self, slice: Slice, spy_price: float, current_date):
        chain = slice.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug(f"{self.Time}: Entry skipped; option chain unavailable.")
            return

        minimum_expiry = current_date + timedelta(days=7)
        contracts = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() >= minimum_expiry
        ]

        if not contracts:
            self.Debug(
                f"{self.Time}: Entry skipped; no eligible call expiration."
            )
            return

        nearest_expiry = min(contract.Expiry.date() for contract in contracts)
        target_strike = 1.01 * spy_price

        candidates = [
            contract for contract in contracts
            if contract.Expiry.date() == nearest_expiry
            and contract.Strike >= target_strike
        ]

        if not candidates:
            self.Debug(
                f"{self.Time}: Entry skipped; no call strike at least 1% OTM."
            )
            return

        selected = min(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        order = self.MarketOrder(
            selected.Symbol,
            1,
            tag="bullish five-minute crossover entry"
        )
        self._entry_order_id = order.OrderId

    def _evaluate_option_exit(self, slice: Slice):
        if self._held_contract is None or self._entry_price is None:
            return

        if self._time_stop_due():
            self._submit_exit("expiration-eve time stop")
            return

        chain = slice.OptionChains.get(self.option_symbol)
        if chain is None:
            return

        contract = next(
            (item for item in chain if item.Symbol == self._held_contract),
            None
        )
        if contract is None:
            return

        bid = contract.BidPrice
        ask = contract.AskPrice

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self._entry_price:
            self._submit_exit("50% profit target")

    def _submit_exit(self, reason: str):
        if not self._has_option_position() or self._held_contract is None:
            return
        if self._exit_order_id is not None:
            return

        quantity = self.Portfolio[self._held_contract].Quantity
        if quantity <= 0:
            return

        self._cancel_exit_order()
        order = self.MarketOrder(
            self._held_contract,
            -quantity,
            tag=reason
        )
        self._exit_order_id = order.OrderId
        self.Debug(f"{self.Time}: Submitted exit: {reason}.")

    def _time_stop_due(self):
        if self._held_contract is None:
            return False

        expiry_date = self._held_contract.ID.Date.date()
        previous_trading_day = expiry_date - timedelta(days=1)

        while not self.Securities[self.spy].Exchange.Hours.IsDateOpen(
            previous_trading_day
        ):
            previous_trading_day -= timedelta(days=1)

        return (
            self.Time.date() == previous_trading_day
            and self.Time.hour == 15
            and self.Time.minute == 45
        )

    def _expiration_processing_required(self, current_date):
        if self._held_contract is None:
            return False
        return current_date >= self._held_contract.ID.Date.date()

    def _has_option_position(self):
        return (
            self._held_contract is not None
            and self.Portfolio[self._held_contract].Quantity > 0
        )

    def _entry_order_is_open(self):
        if self._entry_order_id is None:
            return False

        order = self.Transactions.GetOrderById(self._entry_order_id)
        return order.Status in [
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        ]

    def _cancel_entry_order(self):
        if self._entry_order_id is not None and self._entry_order_is_open():
            self.Transactions.CancelOrder(
                self._entry_order_id,
                "expiration processing"
            )

    def _cancel_exit_order(self):
        if self._exit_order_id is None:
            return

        order = self.Transactions.GetOrderById(self._exit_order_id)
        if order.Status in [
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        ]:
            self.Transactions.CancelOrder(
                self._exit_order_id,
                "replaced by liquidation"
            )
        self._exit_order_id = None

