from datetime import datetime, timedelta, time


class SpyFiveMinuteCallCrossover(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        equity = self.AddEquity(
            "SPY",
            Resolution.Minute,
            extendedMarketHours=False,
            dataNormalizationMode=DataNormalizationMode.Raw
        )
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        self.option_symbol = option.Symbol
        option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-100, 100)
                .Expiration(timedelta(0), timedelta(days=730))
        )

        self.fast_period = 5
        self.slow_period = 20
        self.closes = []

        self._bucket_key = None
        self._bucket_bars = []
        self._bucket_valid = True

        self._entry_ticket = None
        self._entry_symbol = None
        self._entry_filled_quantity = 0
        self._entry_filled_value = 0.0

        self._held_symbol = None
        self._entry_price = None
        self._exit_ticket = None
        self._blocked_entry_date = None

    def OnData(self, slice: Slice):
        current_date = self.Time.date()
        current_time = self.Time.time()

        self._process_expiration_and_exits(slice, current_date, current_time)

        if self.spy not in slice.Bars:
            return

        bar = slice.Bars[self.spy]
        local_start = Extensions.ConvertToUtc(self.TimeZone, bar.Time).astimezone(
            self.TimeZone
        ) if False else bar.Time

        # TradeBar timestamps are minute-period start times in LEAN.
        local_start = bar.Time
        if local_start.tzinfo is not None:
            local_start = local_start.astimezone(self.TimeZone)
        else:
            local_start = self.TimeZone.localize(local_start) if hasattr(
                self.TimeZone, "localize"
            ) else local_start

        minute_of_day = local_start.hour * 60 + local_start.minute
        session_start = 9 * 60 + 30
        session_end = 16 * 60

        if minute_of_day < session_start or minute_of_day >= session_end:
            return

        bucket_index = (minute_of_day - session_start) // 5
        bucket_key = (local_start.date(), bucket_index)

        if self._bucket_key != bucket_key:
            if self._bucket_key is not None:
                self._finish_five_minute_bucket(slice)

            self._bucket_key = bucket_key
            self._bucket_bars = [bar]
            self._bucket_valid = True
        else:
            expected_minute = self._bucket_bars[-1].Time.minute
            if (bar.Time - self._bucket_bars[-1].Time).total_seconds() != 60:
                self._bucket_valid = False
            self._bucket_bars.append(bar)

        if len(self._bucket_bars) > 5:
            self._bucket_valid = False

    def _finish_five_minute_bucket(self, slice: Slice):
        if not self._bucket_valid or len(self._bucket_bars) != 5:
            self._bucket_bars = []
            return

        bars = self._bucket_bars
        consolidated = TradeBar(
            bars[0].Time,
            self.spy,
            bars[0].Open,
            max(x.High for x in bars),
            min(x.Low for x in bars),
            bars[-1].Close,
            sum(x.Volume for x in bars),
            timedelta(minutes=5)
        )

        previous_fast = None
        previous_slow = None

        if len(self.closes) >= self.fast_period:
            previous_fast = sum(self.closes[-self.fast_period:]) / self.fast_period
        if len(self.closes) >= self.slow_period:
            previous_slow = sum(self.closes[-self.slow_period:]) / self.slow_period

        self.closes.append(float(consolidated.Close))

        if len(self.closes) >= self.fast_period and len(self.closes) >= self.slow_period:
            current_fast = sum(self.closes[-self.fast_period:]) / self.fast_period
            current_slow = sum(self.closes[-self.slow_period:]) / self.slow_period

            bar_end = consolidated.EndTime
            if bar_end.tzinfo is not None:
                bar_end = bar_end.astimezone(self.TimeZone)

            eligible_time = time(9, 45) <= bar_end.time() <= time(14, 30)
            bullish_cross = (
                previous_fast is not None and
                previous_slow is not None and
                previous_fast <= previous_slow and
                current_fast > current_slow
            )

            if eligible_time and bullish_cross:
                self._try_enter(consolidated.Close, slice, bar_end.date())

        self._bucket_bars = []

    def _try_enter(self, spy_price, slice: Slice, current_date):
        if self._blocked_entry_date == current_date:
            return

        if self._entry_ticket is not None and not self._is_terminal(
            self._entry_ticket.Status
        ):
            return

        if self._held_symbol is not None and self.Portfolio[
            self._held_symbol
        ].Invested:
            return

