                self.TimeZone, "localize"
            ) else local_start

        minute_of_day = local_start.hour * 60 + local_start.minute
        session_start = 9 * 60 + 30
        session_end = 16 * 60

        if minute_of_day < session_start or minute_of_day >= session_end:
            return

        bucket_index = (minute_of_day - session_start) // 5
        bucket_key = (local_start.date(), bucket_index)

