from collections import deque
from datetime import datetime, timedelta


class SpyCallCrossoverAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        equity = self.AddEquity("SPY", Resolution.Minute)
        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe
            .Strikes(-1000, 1000)
            .Expiration(0, 730)
        )
        self.option_canonical = option.Symbol

        self.consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self.SubscriptionManager.AddConsolidator(self.spy, self.consolidator)
        self.consolidator.DataConsolidated += self.OnFiveMinuteBar

        self.closes = deque(maxlen=20)
        self.pending_signal_time = None

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_option = None
        self.entry_price = None
        self.blocked_date = None
        self.assignment_liquidation_ticket = None

    def OnFiveMinuteBar(self, sender, bar):
        if bar.Symbol != self.spy:
            return

        if len(self.closes) >= 20:
            previous_fast = sum(list(self.closes)[-5:]) / 5.0
            previous_slow = sum(self.closes) / 20.0
        else:
            previous_fast = None
            previous_slow = None

        self.closes.append(float(bar.Close))

        if len(self.closes) < 20:
            return

        current_fast = sum(list(self.closes)[-5:]) / 5.0
        current_slow = sum(self.closes) / 20.0

        bar_end = bar.EndTime
        eligible_time = datetime(
            bar_end.year,
            bar_end.month,
            bar_end.day,
            9,
            45
        ).time() <= bar_end.time() <= datetime(
            bar_end.year,
            bar_end.month,
            bar_end.day,
            14,
            30
        ).time()

        if (
            eligible_time
            and previous_fast is not None
            and previous_fast <= previous_slow
            and current_fast > current_slow
        ):
            self.pending_signal_time = bar_end

    def OnData(self, slice):
        current_date = self.Time.date()

        self.HandleUnexpectedEquityPosition()
        self.HandleExpiration()

        if self.held_option is not None:
            self.EvaluateHeldOption(slice)

        if (
            self.pending_signal_time is not None
            and self.pending_signal_time == self.Time
        ):
            self.pending_signal_time = None
            self.TryEnter(slice)

        if self.blocked_date == current_date:
            self.pending_signal_time = None

    def TryEnter(self, slice):
        if self.blocked_date == self.Time.date():
            return

        if self.held_option is not None and self.Portfolio[self.held_option].Invested:
            return

        if self.IsEntryOrderOpen():
            return

        spy_price = self.Securities[self.spy].Price
        if spy_price <= 0:
            self.Debug("Skipped selection: invalid SPY price.")
            return

        chain = None
        for candidate in slice.OptionChains:
            if candidate.Symbol == self.option_canonical:
                chain = candidate
                break

        if chain is None:
            self.Debug("Skipped selection: option chain unavailable.")
            return

        minimum_expiry = self.Time.date() + timedelta(days=7)
        expiries = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expiries:
            self.Debug("Skipped selection: no expiration at least 7 days away.")
            return

        selected_expiry = expiries[0]
        minimum_strike = 1.01 * spy_price

        contracts = [
            contract
            for contract in chain
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not contracts:
            self.Debug("Skipped selection: no qualifying call contract.")
            return

        selected = min(
            contracts,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="SPY bullish crossover entry"
        )

    def EvaluateHeldOption(self, slice):
        if self.held_option is None:
            return

        security = self.Securities[self.held_option]
        quantity = self.Portfolio[self.held_option].Quantity

        if quantity <= 0:
            return

        expiry_date = security.Symbol.ID.Date.date()
        previous_trading_date = self.PreviousTradingDate(expiry_date)

        if (
            self.Time.date() == previous_trading_date
            and self.Time.time() >= datetime(
                self.Time.year,
                self.Time.month,
                self.Time.day,
                15,
                45
            ).time()
        ):
            self.SubmitExit("expiration time stop")
            return

        if self.exit_ticket is not None and self.IsOrderOpen(self.exit_ticket):
            return

        quote = slice.QuoteBars.get(self.held_option)
        if quote is None or quote.Bid is None or quote.Ask is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close
        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if self.entry_price is not None and midpoint >= 1.5 * self.entry_price:
            self.SubmitExit("50 percent profit target")

    def SubmitExit(self, tag):
        if self.held_option is None:
            return

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity <= 0:
            return

        if self.exit_ticket is not None and self.IsOrderOpen(self.exit_ticket):
            self.exit_ticket.Cancel("Replacing open exit order")

        self.exit_ticket = self.MarketOrder(
            self.held_option,
            -quantity,
            tag=tag
        )

    def HandleExpiration(self):
        if self.held_option is None:
            return

        expiry_date = self.Securities[self.held_option].Symbol.ID.Date.date()
        if self.Time.date() >= expiry_date:
            self.blocked_date = self.Time.date()
            if self.Portfolio[self.held_option].Invested:
                self.SubmitExit("expiration liquidation")
            else:
                self.held_option = None
                self.entry_price = None

    def HandleUnexpectedEquityPosition(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0:
            return

        if (
            self.assignment_liquidation_ticket is None
            or not self.IsOrderOpen(self.assignment_liquidation_ticket)
        ):
            self.Debug("Unexpected exercise or assignment: liquidating SPY.")
            self.assignment_liquidation_ticket = self.MarketOrder(
                self.spy,
                -quantity,
                tag="Unexpected exercise or assignment liquidation"
            )

        self.blocked_date = self.Time.date()

    def OnOrderEvent(self, order_event):
        if order_event.Status == OrderStatus.Filled:
            if (
                self.entry_ticket is not None
                and order_event.OrderId == self.entry_ticket.OrderId
            ):
                self.held_option = order_event.Symbol
                self.entry_price = order_event.FillPrice
                self.Debug(
                    f"Entry filled: {self.held_option} at {self.entry_price}"
                )

            elif (
                self.exit_ticket is not None
                and order_event.OrderId == self.exit_ticket.OrderId
            ):
                if (
                    self.held_option is None
                    or self.Portfolio[order_event.Symbol].Quantity == 0
                ):
                    self.Debug(f"Exit filled: {order_event.Symbol}")
                    self.held_option = None
                    self.entry_price = None
                    self.exit_ticket = None

        if self.entry_ticket is not None:
            if (
                order_event.OrderId == self.entry_ticket.OrderId
                and order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid,
                    OrderStatus.CancelPending
                )
            ):
                self.entry_ticket = None

        message = (order_event.Message or "").lower()
        if "exercise" in message or "assignment" in message:
            self.Debug("Unexpected exercise or assignment handling.")
            self.blocked_date = self.Time.date()
            self.HandleUnexpectedEquityPosition()

    def IsEntryOrderOpen(self):
        return (
            self.entry_ticket is not None
            and self.IsOrderOpen(self.entry_ticket)
        )

    def IsOrderOpen(self, ticket):
        return ticket is not None and ticket.Status in (
            OrderStatus.New,
            OrderStatus.PartiallyFilled,
            OrderStatus.Submitted,
            OrderStatus.UpdateSubmitted,
            OrderStatus.CancelPending
        )

    def PreviousTradingDate(self, date):
        hours = self.Securities[self.spy].Exchange.Hours
        candidate = date - timedelta(days=1)

        while not hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

