        eligible_time = datetime(
            bar_end.year,
            bar_end.month,
            bar_end.day,
            9,
            45
        ).time() <= bar_end.time() <= datetime(
            bar_end.year,
            bar_end.month,
            bar_end.day,
            14,
            30
        ).time()

        if (
            eligible_time
            and previous_fast is not None
            and previous_fast <= previous_slow
            and current_fast > current_slow
        ):
            self.pending_signal_time = bar_end

    def OnData(self, slice):
        current_date = self.Time.date()

        self.HandleUnexpectedEquityPosition()
        self.HandleExpiration()

        if self.held_option is not None:
            self.EvaluateHeldOption(slice)

        if (
            self.pending_signal_time is not None
            and self.pending_signal_time == self.Time
        ):
            self.pending_signal_time = None
            self.TryEnter(slice)

        if self.blocked_date == current_date:
            self.pending_signal_time = None

