            self.Debug("Skipped selection: no expiration at least 7 days away.")
            return

        selected_expiry = expiries[0]
        minimum_strike = 1.01 * spy_price

        contracts = [
            contract
            for contract in chain
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not contracts:
            self.Debug("Skipped selection: no qualifying call contract.")
            return

        selected = min(
            contracts,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="SPY bullish crossover entry"
        )

    def EvaluateHeldOption(self, slice):
        if self.held_option is None:
            return

        security = self.Securities[self.held_option]
        quantity = self.Portfolio[self.held_option].Quantity

        if quantity <= 0:
            return

        expiry_date = security.Symbol.ID.Date.date()
        previous_trading_date = self.PreviousTradingDate(expiry_date)

        if (
            self.Time.date() == previous_trading_date
            and self.Time.time() >= datetime(
                self.Time.year,
                self.Time.month,
                self.Time.day,
                15,
                45
            ).time()
        ):
            self.SubmitExit("expiration time stop")
            return

