from AlgorithmImports import *
from datetime import timedelta


class SpyCallCrossoverAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity("SPY", Resolution.Minute)
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy_symbol = self.spy.Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe.IncludeWeeklys()
            .Strikes(-500, 500)
            .Expiration(0, 1000)
        )

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self.previous_fast = None
        self.previous_slow = None

        self.bucket_end = None
        self.bucket_bars = []
        self.pending_entry = False

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None

        self.no_entry_date = None
        self.spy_liquidation_ticket = None

    def OnData(self, slice: Slice):
        today = self.Time.date()

        self._handle_unexpected_spy_position()
        self._process_expiration_rules()
        self._process_option_exit(slice)

        if self.spy_symbol in slice.Bars:
            self._aggregate_minute_bar(slice.Bars[self.spy_symbol])

        if self.pending_entry:
            self.pending_entry = False
            self._try_enter(slice)

    def _aggregate_minute_bar(self, bar: TradeBar):
        end_time = bar.EndTime
        if end_time.date() != self.Time.date():
            return

        if end_time.time() < TimeSpan.FromHours(9.5).ToTimeSpan():
            return
        if end_time.time() > TimeSpan.FromHours(16).ToTimeSpan():
            return

        minutes_from_midnight = end_time.hour * 60 + end_time.minute
        bucket_end_minutes = ((minutes_from_midnight + 4) // 5) * 5
        bucket_end = end_time.replace(
            hour=bucket_end_minutes // 60,
            minute=bucket_end_minutes % 60,
            second=0,
            microsecond=0,
        )

        if bucket_end.time() < TimeSpan.FromHours(9.583333).ToTimeSpan():
            return

        if self.bucket_end is None:
            self.bucket_end = bucket_end
        elif bucket_end != self.bucket_end:
            self._finalize_five_minute_bar()
            self.bucket_end = bucket_end
            self.bucket_bars = []

        self.bucket_bars.append(bar)

        if len(self.bucket_bars) == 5:
            self._finalize_five_minute_bar()
            self.bucket_end = None
            self.bucket_bars = []

    def _finalize_five_minute_bar(self):
        if len(self.bucket_bars) != 5:
            self.bucket_bars = []
            return

        bars = sorted(self.bucket_bars, key=lambda b: b.EndTime)

        for previous, current in zip(bars, bars[1:]):
            if current.EndTime - previous.EndTime != timedelta(minutes=1):
                self.bucket_bars = []
                return

        bar = TradeBar(
            bars[0].Time,
            self.spy_symbol,
            bars[0].Open,
            max(b.High for b in bars),
            min(b.Low for b in bars),
            bars[-1].Close,
            sum(b.Volume for b in bars),
            timedelta(minutes=5),
        )

        self._on_five_minute_bar(bar)

    def _on_five_minute_bar(self, bar: TradeBar):
        prior_fast = self.fast.Current.Value if self.fast.IsReady else None
        prior_slow = self.slow.Current.Value if self.slow.IsReady else None

        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        if (
            self.fast.IsReady
            and self.slow.IsReady
            and prior_fast is not None
            and prior_slow is not None
        ):
            crossover = (
                prior_fast <= prior_slow
                and self.fast.Current.Value > self.slow.Current.Value
            )

            end_time = bar.EndTime.time()
            if (
                crossover
                and end_time >= TimeSpan.FromHours(9.75).ToTimeSpan()
                and end_time <= TimeSpan.FromHours(14.5).ToTimeSpan()
            ):
                self.pending_entry = True

        self.previous_fast = self.fast.Current.Value if self.fast.IsReady else None
        self.previous_slow = self.slow.Current.Value if self.slow.IsReady else None

    def _try_enter(self, slice: Slice):
        today = self.Time.date()

        if self.no_entry_date == today:
            return

        if self.held_symbol is not None:
            holding = self.Portfolio[self.held_symbol]
            if holding.Invested:
                return

        if self._order_is_open(self.entry_ticket):
            return

        spot = self.Securities[self.spy_symbol].Price
        if spot <= 0:
            self.Debug("Skipped call selection: invalid SPY price.")
            return

        minimum_expiry = today + timedelta(days=7)
        candidates = []

        for chain in slice.OptionChains:
            for contract in chain.Value.Contracts.Values:
                if contract.Right != OptionRight.Call:
                    continue

                expiry = contract.Expiry.date()
                if expiry < minimum_expiry:
                    continue

                if contract.Strike >= 1.01 * spot:
                    candidates.append(contract)

        if not candidates:
            self.Debug("Skipped call selection: no eligible call contract.")
            return

        nearest_expiry = min(c.Expiry.date() for c in candidates)
        candidates = [
            c for c in candidates if c.Expiry.date() == nearest_expiry
        ]

        selected = min(
            candidates,
            key=lambda c: (c.Strike, str(c.Symbol))
        )

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            f"Entry submitted: {selected.Symbol}; "
            f"expiry {nearest_expiry}; strike {selected.Strike}"
        )

    def _process_option_exit(self, slice: Slice):
        if self.held_symbol is None:
            return

        holding = self.Portfolio[self.held_symbol]
        if not holding.Invested:
            return

        if self._order_is_open(self.exit_ticket):
            return

        quote = self._get_current_option_quote(slice, self.held_symbol)
        if quote is None:
            return

        bid, ask = quote
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if self.entry_price is not None and midpoint >= 1.5 * self.entry_price:
            self._submit_option_exit("profit target")

    def _process_expiration_rules(self):
        if self.held_symbol is None:
            return

        holding = self.Portfolio[self.held_symbol]
        if not holding.Invested:
            return

        security = self.Securities[self.held_symbol]
        expiry = security.Symbol.ID.Date.date()
        today = self.Time.date()

        if today >= expiry:
            self.no_entry_date = today
            self._submit_option_exit("expiration protection")
            return

        previous_trading_day = expiry - timedelta(days=1)
        while not self.Securities[self.spy_symbol].Exchange.Hours.IsDateOpen(
            previous_trading_day
        ):
            previous_trading_day -= timedelta(days=1)

        if (
            today == previous_trading_day
            and self.Time.time() >= TimeSpan.FromHours(15.75).ToTimeSpan()
        ):
            self._submit_option_exit("pre-expiration time stop")

    def _submit_option_exit(self, reason: str):
        if self.held_symbol is None:
            return

        if self._order_is_open(self.exit_ticket):
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        if self._order_is_open(self.entry_ticket):
            self.entry_ticket.Cancel("Exit requested before entry completion")

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity
        )
        self.Debug(f"Exit submitted: {reason}; {self.held_symbol}")

    def _get_current_option_quote(self, slice: Slice, symbol: Symbol):
        for chain in slice.OptionChains:
            for contract in chain.Value.Contracts.Values:
                if contract.Symbol == symbol:
                    return contract.BidPrice, contract.AskPrice
        return None

    def _handle_unexpected_spy_position(self):
        holding = self.Portfolio[self.spy_symbol]
        if not holding.Invested:
            return

        if not self._order_is_open(self.spy_liquidation_ticket):
            self.Debug("Unexpected exercise or assignment: liquidating SPY.")
            self.spy_liquidation_ticket = self.MarketOrder(
                self.spy_symbol,
                -holding.Quantity
            )

    def OnOrderEvent(self, order_event: OrderEvent):
        message = (order_event.Message or "").lower()
        is_assignment = bool(getattr(order_event, "IsAssignment", False))
        is_exercise = "exercise" in message or "assignment" in message

        if is_assignment or is_exercise:
            self.Debug("Unexpected exercise or assignment processing detected.")
            self._handle_unexpected_spy_position()

        if self.entry_ticket is not None:
            if order_event.OrderId == self.entry_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.held_symbol = order_event.Symbol
                    self.entry_price = order_event.FillPrice
                    self.Debug(
                        f"Entry filled: {self.held_symbol}; "
                        f"price {self.entry_price}"
                    )
                    self.entry_ticket = None
                elif order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid,
                ):
                    self.Debug("Entry order skipped: order was not filled.")
                    self.entry_ticket = None

        if self.exit_ticket is not None:
            if order_event.OrderId == self.exit_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.Debug(f"Exit filled: {order_event.Symbol}")
                    self.exit_ticket = None
                    self.held_symbol = None
                    self.entry_price = None
                elif order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid,
                ):
                    self.exit_ticket = None

    def _order_is_open(self, ticket):
        if ticket is None:
            return False

        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending,
        )

