from datetime import datetime, timedelta, time


class SpyFiveMinuteCallCrossover(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity("SPY", Resolution.Minute)
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy_symbol = self.spy.Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe.IncludeWeeklys()
            .Strikes(-100, 100)
            .Expiration(timedelta(0), timedelta(days=365))
        )
        self.option_symbol = self.option.Symbol

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self.previous_fast = None
        self.previous_slow = None

        self._bucket_start = None
        self._bucket_bars = {}
        self._latest_slice = None

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.expiration_block_date = None
        self.blocked_entry_date = None

    def OnData(self, slice: Slice):
        self._latest_slice = slice

        if self.Portfolio[self.spy_symbol].Quantity != 0:
            self.Debug("Unexpected SPY equity position detected; liquidating immediately.")
            self.MarketOrder(
                self.spy_symbol,
                -self.Portfolio[self.spy_symbol].Quantity
            )
            self.blocked_entry_date = self.Time.date()

        if self.held_symbol is not None:
            self._process_option_exits(slice)

        if self.held_symbol is not None:
            expiry_date = self.expiration_block_date
            if expiry_date is not None and self.Time.date() >= expiry_date:
                self.Debug("Expiration processing began; liquidating held option.")
                self.blocked_entry_date = self.Time.date()
                self._submit_exit("expiration")

        bar = slice.Bars.get(self.spy_symbol)
        if bar is not None:
            self._process_minute_bar(bar)

        if (
            self._pending_signal_time is not None
            and self._pending_signal_time == self.Time
        ):
            self._pending_signal_time = None
            self._evaluate_entry(slice)

    def OnEndOfAlgorithm(self):
        self._pending_signal_time = None

    def _process_minute_bar(self, bar: TradeBar):
        local_time = bar.Time
        if local_time.tzinfo is not None:
            local_time = local_time.replace(tzinfo=None)

        if not (
            time(9, 31) <= local_time.time() <= time(16, 0)
        ):
            return

        minute_index = local_time.hour * 60 + local_time.minute
        session_start = 9 * 60 + 31
        bucket_offset = ((minute_index - session_start) // 5) * 5
        bucket_start_minutes = session_start + bucket_offset
        bucket_start = datetime(
            local_time.year,
            local_time.month,
            local_time.day,
            bucket_start_minutes // 60,
            bucket_start_minutes % 60
        )

        if self._bucket_start is None:
            self._bucket_start = bucket_start

        if bucket_start != self._bucket_start:
            self._emit_bucket_if_complete()
            self._bucket_start = bucket_start
            self._bucket_bars = {}

        self._bucket_bars[local_time.minute] = bar

        if len(self._bucket_bars) == 5:
            self._emit_bucket_if_complete()

    def _emit_bucket_if_complete(self):
        if self._bucket_start is None:
            return

        expected_minutes = [
            (self._bucket_start.hour * 60 + self._bucket_start.minute + i) % 60
            for i in range(5)
        ]

        if set(self._bucket_bars.keys()) != set(expected_minutes):
            self._bucket_bars = {}
            return

        bars = [
            self._bucket_bars[minute]
            for minute in expected_minutes
        ]

        five_minute_bar = TradeBar(
            self._bucket_start,
            self.spy_symbol,
            bars[0].Open,
            max(x.High for x in bars),
            min(x.Low for x in bars),
            bars[-1].Close,
            sum(x.Volume for x in bars),
            timedelta(minutes=5)
        )

        self._bucket_bars = {}
        self._on_five_minute_bar(five_minute_bar)

    def _on_five_minute_bar(self, bar: TradeBar):
        end_time = bar.Time + timedelta(minutes=5)
        end_clock = end_time.time()

        old_fast = self.fast.Current.Value if self.fast.IsReady else None
        old_slow = self.slow.Current.Value if self.slow.IsReady else None

        self.fast.Update(IndicatorDataPoint(end_time, bar.Close))
        self.slow.Update(IndicatorDataPoint(end_time, bar.Close))

        bullish_cross = (
            old_fast is not None
            and old_slow is not None
            and self.fast.IsReady
            and self.slow.IsReady
            and old_fast <= old_slow
            and self.fast.Current.Value > self.slow.Current.Value
        )

        self.previous_fast = self.fast.Current.Value if self.fast.IsReady else None
        self.previous_slow = self.slow.Current.Value if self.slow.IsReady else None

        if bullish_cross and time(9, 45) <= end_clock <= time(14, 30):
            self._pending_signal_time = self.Time

