        if self.blocked_entry_date == self.Time.date():
            return

        if self.held_symbol is not None or self._entry_order_is_open():
            return

        spy_bar = slice.Bars.get(self.spy_symbol)
        if spy_bar is None:
            self.Debug("Skipped call selection: current SPY price unavailable.")
            return

        chain = self._get_option_chain(slice)
        if chain is None:
            self.Debug("Skipped call selection: option chain unavailable.")
            return

        minimum_expiry = self.Time.date() + timedelta(days=7)
        calls = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() >= minimum_expiry
        ]

        if not calls:
            self.Debug("Skipped call selection: no eligible call contracts.")
            return

        nearest_expiry = min(contract.Expiry.date() for contract in calls)
        target_strike = float(spy_bar.Close) * 1.01

        candidates = [
            contract for contract in calls
            if contract.Expiry.date() == nearest_expiry
            and float(contract.Strike) >= target_strike
        ]

        if not candidates:
            self.Debug("Skipped call selection: no strike at least 1% OTM.")
            return

        selected = min(
            candidates,
            key=lambda contract: (float(contract.Strike), str(contract.Symbol))
        )

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug("Call entry submitted: " + str(selected.Symbol))

    def _process_option_exits(self, slice: Slice):
        if self.held_symbol is None or self.entry_price is None:
            return

        contract = self._get_contract(slice, self.held_symbol)
        if contract is not None:
            bid = float(contract.BidPrice)
            ask = float(contract.AskPrice)

            if bid > 0 and ask > 0:
                midpoint = (bid + ask) / 2.0
                if midpoint >= 1.5 * float(self.entry_price):
                    self._submit_exit("profit target")

        expiry_date = self.expiration_block_date
        if expiry_date is not None:
            previous_trading_day = self._previous_trading_day(expiry_date)
            if (
                self.Time.date() == previous_trading_day
                and self.Time.time() >= time(15, 45)
            ):
                self._submit_exit("expiration time stop")

    def _submit_exit(self, reason):
        if self.held_symbol is None:
            return

        if self._exit_order_is_open():
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        if self.exit_ticket is not None:
            self.exit_ticket.Cancel("Replacing prior exit order.")

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity
        )
        self.Debug("Option exit submitted: " + reason)

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None:
            if order_event.OrderId == self.entry_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.held_symbol = self.entry_ticket.Symbol
                    self.entry_price = order_event.FillPrice
                    self.expiration_block_date = (
                        self.held_symbol.ID.Date.date()
                    )
                    self.entry_ticket = None
                    self.Debug(
                        "Call entry filled at " + str(self.entry_price)
                    )
                elif order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid,
                    OrderStatus.Error
                ):
                    self.Debug("Call entry order did not fill.")
                    self.entry_ticket = None

        if self.exit_ticket is not None:
            if order_event.OrderId == self.exit_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.Debug("Call position exited.")
                    self.exit_ticket = None
                    self.held_symbol = None
                    self.entry_price = None
                    self.expiration_block_date = None
                elif order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid,
                    OrderStatus.Error
                ):
                    self.exit_ticket = None

        order = self.Transactions.GetOrderById(order_event.OrderId)
        if order is not None:
            order_type = str(order.Type).lower()
            message = str(order_event.Message).lower()
            if (
                "exercise" in order_type
                or "assignment" in order_type
                or "exercise" in message
                or "assignment" in message
            ):
                self.Debug("Unexpected option exercise or assignment handled.")
                self.blocked_entry_date = self.Time.date()
                if self.Portfolio[self.spy_symbol].Quantity != 0:
                    self.MarketOrder(
                        self.spy_symbol,
                        -self.Portfolio[self.spy_symbol].Quantity
                    )

    def _get_option_chain(self, slice: Slice):
        chain = slice.OptionChains.get(self.option_symbol)
        if chain is not None:
            return chain

        for candidate in slice.OptionChains.Values:
            if candidate.Symbol == self.option_symbol:
                return candidate

        return None

    def _get_contract(self, slice: Slice, symbol: Symbol):
        chain = self._get_option_chain(slice)
        if chain is None:
            return None

        for contract in chain:
            if contract.Symbol == symbol:
                return contract

        return None

    def _entry_order_is_open(self):
        return (
            self.entry_ticket is not None
            and self.entry_ticket.Status in (
                OrderStatus.New,
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled
            )
        )

    def _exit_order_is_open(self):
        return (
            self.exit_ticket is not None
            and self.exit_ticket.Status in (
                OrderStatus.New,
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled
            )
        )

    def _previous_trading_day(self, date_value):
        candidate = date_value - timedelta(days=1)
        while not self.Securities[self.spy_symbol].Exchange.Hours.IsDateOpen(
            datetime(candidate.year, candidate.month, candidate.day)
        ):
            candidate -= timedelta(days=1)
        return candidate.date() if hasattr(candidate, "date") else candidate

    @property
    def _pending_signal_time(self):
        return getattr(self, "__pending_signal_time", None)

    @_pending_signal_time.setter
    def _pending_signal_time(self, value):
        setattr(self, "__pending_signal_time", value)

