from AlgorithmImports import *
from datetime import datetime, timedelta, time


class SpyBullishCallAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            Market.USA,
            fillForward=False,
            leverage=1,
            extendedMarketHours=False
        )
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy_symbol = self.spy.Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 730)
        )
        self.option_symbol = self.option.Symbol

        self._five_minute_bucket = None
        self._minute_bars = {}
        self._closes = []

        self._entry_ticket = None
        self._exit_ticket = None
        self._held_symbol = None
        self._entry_price = None
        self._expiration_date = None
        self._time_stop_date = None
        self._no_entry_dates = set()
        self._assignment_liquidation_logged = False

    def OnData(self, slice: Slice):
        current_date = self.Time.date()

        self._handle_unexpected_spy_position()
        self._process_expiration(current_date)
        self._evaluate_option_exit(slice)

        if self.spy_symbol not in slice.Bars:
            return

        minute_bar = slice.Bars[self.spy_symbol]
        self._process_minute_bar(minute_bar, slice)

    def _process_minute_bar(self, minute_bar: TradeBar, slice: Slice):
        minute_time = datetime(
            minute_bar.Time.year,
            minute_bar.Time.month,
            minute_bar.Time.day,
            minute_bar.Time.hour,
            minute_bar.Time.minute
        )

        if minute_time.time() < time(9, 30) or minute_time.time() >= time(16, 0):
            return

        minutes_from_open = (
            minute_time.hour * 60 + minute_time.minute
            - (9 * 60 + 30)
        )
        bucket_start = minute_time - timedelta(
            minutes=minutes_from_open % 5
        )
        bucket_end = bucket_start + timedelta(minutes=5)

        if self._five_minute_bucket is None:
            self._five_minute_bucket = bucket_start

        if bucket_start != self._five_minute_bucket:
            self._finalize_five_minute_bucket(slice)
            self._minute_bars = {}
            self._five_minute_bucket = bucket_start

        self._minute_bars[minute_time] = minute_bar

        if minute_time == bucket_end - timedelta(minutes=1):
            self._finalize_five_minute_bucket(slice)
            self._minute_bars = {}
            self._five_minute_bucket = None

    def _finalize_five_minute_bucket(self, slice: Slice):
        if self._five_minute_bucket is None:
            return

        bucket_start = self._five_minute_bucket
        expected_times = [
            bucket_start + timedelta(minutes=i)
            for i in range(5)
        ]

        if any(t not in self._minute_bars for t in expected_times):
            return

        bars = [self._minute_bars[t] for t in expected_times]

        consolidated = TradeBar(
            bucket_start,
            self.spy_symbol,
            bars[0].Open,
            max(b.High for b in bars),
            min(b.Low for b in bars),
            bars[-1].Close,
            sum(b.Volume for b in bars),
            timedelta(minutes=5)
        )

        self._on_five_minute_bar(consolidated, slice)

    def _on_five_minute_bar(self, bar: TradeBar, slice: Slice):
        if len(self._closes) >= 20:
            previous_fast = sum(self._closes[-5:]) / 5
            previous_slow = sum(self._closes[-20:]) / 20
        else:
            previous_fast = None
            previous_slow = None

        self._closes.append(bar.Close)
        if len(self._closes) > 20:
            self._closes.pop(0)

        if len(self._closes) < 20:
            return

        current_fast = sum(self._closes[-5:]) / 5
        current_slow = sum(self._closes[-20:]) / 20

        bullish_crossover = (
            previous_fast is not None
            and previous_slow is not None
            and previous_fast <= previous_slow
            and current_fast > current_slow
        )

        bar_end_time = bar.EndTime.time()
        eligible_time = time(9, 45) <= bar_end_time <= time(14, 30)

        if bullish_crossover and eligible_time:
            self._try_enter_call(slice, bar.Close)

    def _try_enter_call(self, slice: Slice, spy_price):
        current_date = self.Time.date()

        if current_date in self._no_entry_dates:
            return

        if self._held_symbol is not None:
            return

        if self._is_order_open(self._entry_ticket):
            return

        if self._is_order_open(self._exit_ticket):
            return

        candidates = []

        for chain in slice.OptionChains.Values:
            for contract in chain:
                if contract.Right != OptionRight.Call:
                    continue

                expiration_date = contract.Expiry.date()
                if expiration_date < current_date + timedelta(days=7):
                    continue

                if contract.Strike < 1.01 * spy_price:
                    continue

                candidates.append(contract)

        if not candidates:
            self.Debug("Skipped call selection: no eligible contract.")
            return

        nearest_expiration = min(c.Expiry.date() for c in candidates)
        candidates = [
            c for c in candidates
            if c.Expiry.date() == nearest_expiration
        ]

        selected = min(
            candidates,
            key=lambda c: (c.Strike, str(c.Symbol))
        )

        self._entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover call entry"
        )

        self.Debug("Call entry submitted: " + str(selected.Symbol))

